	$sseo['posts']['analysis'] = $sseo_an_post;
	$sseo_an_find              = static fn( array $result, string $id ): array => array_values( array_filter( $result['checks'], static fn( array $check ): bool => $id === $check['id'] ) );
	$sseo_an_status            = static fn( array $result, string $id ): string => $sseo_an_find( $result, $id )[0]['status'] ?? 'none';
	$sseo_an_text              = static fn( array $result, string $id ): string => $sseo_an_find( $result, $id )[0]['text'] ?? '';
	$sseo_an_field             = Simple_SEO_Fields::get( 'keyphrase' );
	sseo_check( 'the keyphrase fields: posts only, in the analysis group', array( 'post' ) === $sseo_an_field['objects'] && 'analysis' === $sseo_an_field['group'] && 'textarea' === Simple_SEO_Fields::get( 'keyphrases' )['type'] && array( 'post' ) === Simple_SEO_Fields::get( 'keyphrases' )['objects'] && 'Content analysis' === Simple_SEO_Fields::group_heading( 'analysis' ) );

	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Short text.</p>', 'title' => '', 'description' => '', 'keyphrase' => ' ' ) );
	sseo_check( 'no keyphrase: a note, and the checks of the page only', 'info' === $sseo_an_status( $sseo_an, 'keyphrase' ) && 'none' === $sseo_an_status( $sseo_an, 'keyphrase_title' ) && 'bad' === $sseo_an_status( $sseo_an, 'length' ) && 'bad' === $sseo_an_status( $sseo_an, 'title_length' ) && 'bad' === $sseo_an_status( $sseo_an, 'description_length' ) && 'ok' === $sseo_an_status( $sseo_an, 'images' ) && 'none' === $sseo_an_status( $sseo_an, 'alt' ), $sseo_an['checks'] );
	sseo_check( 'a note counts for nothing; the score of the rest and its rating', 2 === $sseo_an['words'] && 25 === $sseo_an['score'] && 'bad' === $sseo_an['rating'], $sseo_an );

	$sseo_an_body = '<p>Ключова фраза на початку тексту.</p><h2>Де шукати ключові фрази</h2><p>' . str_repeat( 'Слово ', 300 ) . 'і трохи ключової фрази.</p>'
		. '<p><a href="/inside/">всередині</a> <a href="/second/">ще</a> <a href="https://example.org/">назовні</a></p><img src="/a.png" alt="Ключова фраза на фото">';
	$sseo_an_good = array(
		'content'     => $sseo_an_body,
		'title'       => 'Ключова фраза: як знайти і де вжити – IT',
		'description' => 'Що таке ключова фраза і чому вона важлива для пошуку сторінки в Google та інших пошуковиках.',
		'url'         => home_url( '/kliuchova-fraza/' ),
		'keyphrase'   => '  Ключова   фраза ',
	);
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), $sseo_an_good );
	$sseo_an_ids = array( 'keyphrase_length', 'keyphrase_title', 'keyphrase_description', 'keyphrase_slug', 'keyphrase_intro', 'keyphrase_headings', 'keyphrase_density', 'keyphrase_images', 'keyphrase_used', 'length', 'links_internal', 'links_external', 'images', 'title_length', 'description_length' );
	sseo_check( 'a page that does it all: every check good, in their order, other forms of the words found', $sseo_an_ids === array_column( $sseo_an['checks'], 'id' ) && array( 'good' ) === array_values( array_unique( array_column( $sseo_an['checks'], 'status' ) ) ) && 100 === $sseo_an['score'] && 'good' === $sseo_an['rating'], $sseo_an['checks'] );
	sseo_check( 'the counts are told', str_contains( $sseo_an_text( $sseo_an, 'keyphrase_density' ), ' 3 ' ) && str_contains( $sseo_an_text( $sseo_an, 'links_internal' ), ': 2.' ) && str_contains( $sseo_an_text( $sseo_an, 'links_external' ), ': 1.' ) && str_contains( $sseo_an_text( $sseo_an, 'length' ), '316' ), $sseo_an['checks'] );

	$sseo_an = Simple_SEO_Analysis::run(
		get_post( $sseo_an_post ),
		array(
			'content'     => '<h2>Про інше</h2><p>Перший абзац без неї.</p><p>Другий теж.</p><p>Ось ключова фраза.</p><img src="/a.png"><img src="/c.png" alt=""><img src="/b.png" alt="Фото">',
			'title'       => 'Зовсім інша назва цієї сторінки, задовга для пошукової видачі – IT',
			'description' => 'Короткий опис.',
			'url'         => home_url( '/insha-adresa/' ),
			'keyphrase'   => 'ключова фраза',
		)
	);
	sseo_check( 'the keyphrase missing from the title, description, address, first paragraph and subheadings', 'bad' === $sseo_an_status( $sseo_an, 'keyphrase_title' ) && 'bad' === $sseo_an_status( $sseo_an, 'keyphrase_description' ) && 'ok' === $sseo_an_status( $sseo_an, 'keyphrase_slug' ) && 'bad' === $sseo_an_status( $sseo_an, 'keyphrase_intro' ) && 'ok' === $sseo_an_status( $sseo_an, 'keyphrase_headings' ) && 'ok' === $sseo_an_status( $sseo_an, 'keyphrase_images' ), $sseo_an['checks'] );
	sseo_check( 'a short text with the keyphrase once is enough', 'good' === $sseo_an_status( $sseo_an, 'keyphrase_density' ) );
	sseo_check( 'images without alt text are counted; no links of either kind', 'bad' === $sseo_an_status( $sseo_an, 'alt' ) && str_contains( $sseo_an_text( $sseo_an, 'alt' ), ': 2.' ) && 'ok' === $sseo_an_status( $sseo_an, 'links_internal' ) && 'ok' === $sseo_an_status( $sseo_an, 'links_external' ) && 'good' === $sseo_an_status( $sseo_an, 'images' ), $sseo_an['checks'] );
	sseo_check( 'a title too long and a description too short', 'ok' === $sseo_an_status( $sseo_an, 'title_length' ) && str_contains( $sseo_an_text( $sseo_an, 'title_length' ), 'cut' ) && 'ok' === $sseo_an_status( $sseo_an, 'description_length' ) && str_contains( $sseo_an_text( $sseo_an, 'description_length' ), 'short' ), $sseo_an['checks'] );
	// Wide letters and narrow ones: the same number of characters, a different width.
	$sseo_an_wide   = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Текст.</p>', 'title' => trim( str_repeat( 'Жим ', 14 ) ), 'description' => trim( str_repeat( 'Шум ', 38 ) ) ) );
	$sseo_an_narrow = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Текст.</p>', 'title' => trim( str_repeat( 'ill ', 14 ) ), 'description' => trim( str_repeat( 'ill ', 43 ) ) ) );
	sseo_check( 'the length of a title and a description by their width: 55 wide characters of a title are cut (680 of 600 pixels), 55 narrow ones fit; 151 wide characters of a description are cut, 171 narrow ones fit', 'ok' === $sseo_an_status( $sseo_an_wide, 'title_length' ) && str_contains( $sseo_an_text( $sseo_an_wide, 'title_length' ), '55 characters, 680 pixels wide of 600' ) && 'ok' === $sseo_an_status( $sseo_an_wide, 'description_length' ) && str_contains( $sseo_an_text( $sseo_an_wide, 'description_length' ), '151 characters, 1,264 pixels wide of 920' ) && 'good' === $sseo_an_status( $sseo_an_narrow, 'title_length' ) && 'good' === $sseo_an_status( $sseo_an_narrow, 'description_length' ) && str_contains( $sseo_an_text( $sseo_an_narrow, 'description_length' ), '171 characters, a good length' ), array( $sseo_an_wide['checks'], $sseo_an_narrow['checks'] ) );

	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Ключова фраза. Ключова фраза. Ключова фраза. Ключова фраза.</p>', 'keyphrase' => 'ключова фраза' ) );
	sseo_check( 'the keyphrase too often, without subheadings or images to check', 'bad' === $sseo_an_status( $sseo_an, 'keyphrase_density' ) && str_contains( $sseo_an_text( $sseo_an, 'keyphrase_density' ), '100' ) && 'none' === $sseo_an_status( $sseo_an, 'keyphrase_headings' ) && 'none' === $sseo_an_status( $sseo_an, 'keyphrase_images' ), $sseo_an['checks'] );
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Ключова фраза ' . str_repeat( 'слово ', 500 ) . '</p>', 'keyphrase' => 'ключова фраза' ) );
	sseo_check( 'the keyphrase rare in a long text', 'ok' === $sseo_an_status( $sseo_an, 'keyphrase_density' ), $sseo_an_text( $sseo_an, 'keyphrase_density' ) );
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Нічого.</p>', 'keyphrase' => 'ключова фраза' ) );
	sseo_check( 'the keyphrase not in the text at all', 'bad' === $sseo_an_status( $sseo_an, 'keyphrase_density' ) );
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => '<p>Text.</p>', 'keyphrase' => 'one two three four five' ) );
	sseo_check( 'a keyphrase of five words is long', 'ok' === $sseo_an_status( $sseo_an, 'keyphrase_length' ) );

	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => $sseo_an_body, 'keyphrase' => '', 'keyphrases' => "інша фраза\nслово\n\nінша фраза\nп'ята\nшоста\nсьома" ) );
	$sseo_an_more = $sseo_an_find( $sseo_an, 'more_keyphrases' );
	sseo_check( 'more keyphrases: each once, four at most, counted in the text', 4 === count( $sseo_an_more ) && 'bad' === $sseo_an_more[0]['status'] && str_contains( $sseo_an_more[0]['text'], 'інша фраза' ) && 'good' === $sseo_an_more[1]['status'] && str_contains( $sseo_an_more[1]['text'], '300' ) && str_contains( $sseo_an_more[3]['text'], 'шоста' ), $sseo_an_more );

	// As saved: the post's content, its fields, its title and address as the site shows them.
	wp_update_post( array( 'ID' => $sseo_an_post, 'post_content' => $sseo_an_body ) );
	update_post_meta( $sseo_an_post, '_simple_seo_keyphrase', 'Ключова фраза' );
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ) );
	sseo_check( 'as saved: the post\'s own text, keyphrase, title and address', 'good' === $sseo_an_status( $sseo_an, 'keyphrase_title' ) && 'good' === $sseo_an_status( $sseo_an, 'keyphrase_slug' ) && 'good' === $sseo_an_status( $sseo_an, 'keyphrase_intro' ) && 'bad' !== $sseo_an_status( $sseo_an, 'description_length' ), $sseo_an['checks'] );

	$sseo_an_other = wp_insert_post( array( 'post_title' => 'Other page on the phrase', 'post_status' => 'publish' ) );
	$sseo_an_trash = wp_insert_post( array( 'post_title' => 'Trashed page on the phrase', 'post_status' => 'trash' ) );
	$sseo['posts']['analysis_other'] = $sseo_an_other;
	$sseo['posts']['analysis_trash'] = $sseo_an_trash;
	update_post_meta( $sseo_an_other, '_simple_seo_keyphrase', 'КЛЮЧОВА ФРАЗА' );
	update_post_meta( $sseo_an_trash, '_simple_seo_keyphrase', 'ключова фраза' );
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), $sseo_an_good );
	sseo_check( 'the same focus keyphrase on another page, whatever its case; a trashed page does not count', 'ok' === $sseo_an_status( $sseo_an, 'keyphrase_used' ) && str_contains( $sseo_an_text( $sseo_an, 'keyphrase_used' ), '"Other page on the phrase"' ) && ! str_contains( $sseo_an_text( $sseo_an, 'keyphrase_used' ), 'Trashed' ), $sseo_an_text( $sseo_an, 'keyphrase_used' ) );
	delete_post_meta( $sseo_an_other, '_simple_seo_keyphrase' );

	sseo_check( 'words: lower case, apostrophes alike', array( "мар'яна", "п'є", 'seo-аналіз' ) === Simple_SEO_Analysis::words( 'Мар’яна пʼє SEO-аналіз!' ) );
	sseo_check( 'stems: two letters off a long word, one off a middle one, short ones whole', 'анал' === Simple_SEO_Analysis::stem( 'аналіз' ) && 'фраз' === Simple_SEO_Analysis::stem( 'фраза' ) && 'seo' === Simple_SEO_Analysis::stem( 'seo' ) && 'page' === Simple_SEO_Analysis::stem( 'pages' ) && 'сай' === Simple_SEO_Analysis::stem( 'сайт' ) );
	sseo_check( 'contains: every stem, in any order; nothing to look for is not found', Simple_SEO_Analysis::contains( array( 'фрази', 'ключові' ), array( 'ключо', 'фраз' ) ) && ! Simple_SEO_Analysis::contains( array( 'ключові' ), array( 'ключо', 'фраз' ) ) && ! Simple_SEO_Analysis::contains( array( 'x' ), array() ) );
	sseo_check( 'occurrences: the stems one after another, not overlapping', 2 === Simple_SEO_Analysis::occurrences( array( 'a', 'b', 'a', 'b', 'a' ), array( 'a', 'b' ) ) && 0 === Simple_SEO_Analysis::occurrences( array( 'b', 'a' ), array( 'a', 'b' ) ) && 3 === Simple_SEO_Analysis::occurrences( array( 'a', 'a', 'a' ), array( 'a' ) ) && 1 === Simple_SEO_Analysis::occurrences( array( 'a', 'a', 'a' ), array( 'a', 'a' ) ) );
	sseo_check( 'Cyrillic in Latin letters, as slugs spell it', 'shchastia izhak kliuchova' === Simple_SEO_Analysis::latin( 'Щастя Їжак ключова' ) );

	// The REST route the editor sends its text to.
	$sseo_an_rest = static function ( int $id, array $params ): WP_REST_Response {
		$request = new WP_REST_Request( 'POST', '/simple-seo/v1/analysis/' . $id );
		$request->set_body_params( $params );

		return rest_do_request( $request );
	};
	$sseo_an_response = $sseo_an_rest( $sseo_an_post, array_merge( $sseo_an_good, array( 'content' => '<p>Ключова фраза одна.</p>' ) ) );
	sseo_check( 'REST: the analysis of the text sent', 200 === $sseo_an_response->get_status() && 3 === $sseo_an_response->get_data()['words'] && 'good' === $sseo_an_status( $sseo_an_response->get_data(), 'keyphrase_used' ) && 'good' === $sseo_an_status( $sseo_an_response->get_data(), 'keyphrase_title' ), $sseo_an_response->get_data() );
	wp_set_current_user( $sseo_au );
	sseo_check( 'REST: not for an author on someone else\'s post', in_array( $sseo_an_rest( $sseo_an_post, array() )->get_status(), array( 401, 403 ), true ) );
	wp_set_current_user( $sseo_u['subscriber'] );
	$sseo_an_response = $sseo_an_rest( $sseo_an_post, $sseo_an_good );
	sseo_check( 'REST: not for whoever cannot edit the post', in_array( $sseo_an_response->get_status(), array( 401, 403 ), true ), $sseo_an_response->get_status() );
	wp_set_current_user( $sseo_ed );
	$sseo_an_private = wp_insert_post( array( 'post_type' => 'sseo_private', 'post_title' => 'No fields here', 'post_status' => 'publish' ) );
	$sseo['posts']['analysis_private'] = $sseo_an_private;
	sseo_check( 'REST: not for a type without SEO fields, nor for a post that is not there', in_array( $sseo_an_rest( $sseo_an_private, array() )->get_status(), array( 401, 403 ), true ) && in_array( $sseo_an_rest( 99999999, array() )->get_status(), array( 401, 403, 404 ), true ) );

	update_post_meta( $sseo_an_post, '_simple_seo_keyphrases', "\"quoted\" <i>tag</i>" );
	$sseo_html = Simple_SEO_Analysis::render( get_post( $sseo_an_post ) );
	$sseo_an   = Simple_SEO_Analysis::run( get_post( $sseo_an_post ) );
	preg_match( '/data-simple-seo-analysis="([^"]*)"/', $sseo_html, $sseo_m );
	$sseo_json = json_decode( html_entity_decode( $sseo_m[1] ?? '', ENT_QUOTES, 'UTF-8' ), true );
	sseo_check( 'the panel: the route, a nonce and the labels for the script', is_array( $sseo_json ) && rest_url( 'simple-seo/v1/analysis/' . $sseo_an_post ) === $sseo_json['url'] && false !== wp_verify_nonce( $sseo_json['nonce'], 'wp_rest' ) && str_contains( $sseo_json['score'], '%s' ), $sseo_json );
	sseo_check(
		'the panel: SEO and then readability, each with the score of the saved post and a line for each check',
		str_contains( $sseo_html, '<div class="simple-seo-analysis-part" data-part="seo"><p class="simple-seo-analysis-score is-' . $sseo_an['rating'] . '"><strong>SEO score: ' . $sseo_an['score'] . ' of 100</strong>' )
			&& str_contains( $sseo_html, '<div class="simple-seo-analysis-part" data-part="readability"><p class="simple-seo-analysis-score is-' . $sseo_an['readability']['rating'] . '"><strong>Readability: ' . $sseo_an['readability']['score'] . ' of 100</strong>' )
			&& count( $sseo_an['checks'] ) + count( $sseo_an['readability']['checks'] ) === substr_count( $sseo_html, '<li class="is-' ) - substr_count( $sseo_html, '<li class="is-none">' )
			&& strpos( $sseo_html, 'data-part="seo"' ) < strpos( $sseo_html, 'data-part="readability"' )
			&& 'Readability: %s of 100' === $sseo_json['readability'] && 'Readability' === $sseo_json['unscored'],
		$sseo_html
	);
	sseo_check( 'the panel escapes what it prints', str_contains( $sseo_html, '&quot;quoted&quot;' ) && ! str_contains( $sseo_html, '<i>' ) );
	$sseo_html = sseo_capture( static fn() => Simple_SEO_Editor::render_meta_box( get_post( $sseo_an_post ) ) );
	sseo_check( 'meta box: the panel after the keyphrases', strpos( $sseo_html, 'simple-seo-analysis"' ) > strpos( $sseo_html, 'id="simple-seo-field-keyphrases"' ) && str_contains( $sseo_html, 'name="simple_seo[keyphrase]"' ) );
	$sseo_html = sseo_capture( static fn() => Simple_SEO_Editor::render_term_fields( get_term( $sseo_cat_id ) ) );
	sseo_check( 'term screen: no keyphrases and no analysis', ! str_contains( $sseo_html, 'simple_seo[keyphrase]' ) && ! str_contains( $sseo_html, 'simple-seo-analysis' ) );
	wp_set_current_user( $sseo_u['administrator'] );

	// ------------------------------------------------------------------------------------------
	sseo_section( 'Readability and scores' );

	$sseo_rd       = static fn( string $html ): array => Simple_SEO_Readability::run( Simple_SEO_Content::parse( $html ) );
	// A sentence of so many words: it starts with a capital, as the next sentence must.
	$sseo_rd_words = static fn( int $count ): string => 'Слово' . str_repeat( ' слово', $count - 1 );
	// Sentences of four words, each starting with a word of its own.
	$sseo_rd_short = static fn( int $from, int $count ): string => implode( ' ', array_map( static fn( int $i ): string => "Думка{$i} коротка і ясна.", range( $from, $from + $count - 1 ) ) );
	$sseo_rd_long  = $sseo_rd_words( 21 ) . '.';

	$sseo_vals = Simple_SEO_Readability::sentences( 'Перше речення. Друге! А третє? «Цитата.» Ну… Далі т. зв. скорочення… і e.g. this. ... Кінець' );
	sseo_check( 'sentences: after a stop, a question or an exclamation mark, an ellipsis (a closing quote too), before anything but a small letter; a piece without a word is none', array( 'Перше речення.', 'Друге!', 'А третє?', '«Цитата.»', 'Ну…', 'Далі т. зв. скорочення… і e.g. this.', 'Кінець' ) === $sseo_vals, $sseo_vals );

	$sseo_rd_good = '';
	foreach ( array( 1, 31, 61 ) as $sseo_from ) {
		$sseo_rd_good .= '<h2>Частина ' . $sseo_from . '</h2><p>' . $sseo_rd_short( $sseo_from, 10 ) . '</p><p>' . $sseo_rd_short( $sseo_from + 10, 10 ) . '</p><p>' . $sseo_rd_short( $sseo_from + 20, 10 ) . '</p>';
	}
	$sseo_rd_result = $sseo_rd( $sseo_rd_good );
	sseo_check( 'a text that reads well: every check good, in their order, score 100', array( 'sentence_length', 'paragraph_length', 'subheadings', 'sentence_starts' ) === array_column( $sseo_rd_result['checks'], 'id' ) && array( 'good' ) === array_values( array_unique( array_column( $sseo_rd_result['checks'], 'status' ) ) ) && 100 === $sseo_rd_result['score'] && 'good' === $sseo_rd_result['rating'], $sseo_rd_result );
	sseo_check( 'the counts are told', str_contains( $sseo_an_text( $sseo_rd_result, 'sentence_length' ), '20 words: 0 of 90' ) && str_contains( $sseo_an_text( $sseo_rd_result, 'paragraph_length' ), 'has 40 words' ) && str_contains( $sseo_an_text( $sseo_rd_result, 'subheadings' ), 'than 120 words' ), $sseo_rd_result );

	// Long sentences: more than 20 words; a quarter of them reads well, more than a third does not.
	$sseo_vals = array(
		$sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_words( 20 ) . '. ' . $sseo_rd_words( 20 ) . '.</p>' ), 'sentence_length' ),
		$sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_long . ' ' . $sseo_rd_short( 1, 3 ) . '</p>' ), 'sentence_length' ),
		$sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_long . ' ' . $sseo_rd_short( 1, 2 ) . '</p>' ), 'sentence_length' ),
		$sseo_an_status( $sseo_rd( '<p>' . str_repeat( $sseo_rd_long . ' ', 7 ) . $sseo_rd_short( 1, 13 ) . '</p>' ), 'sentence_length' ),
		$sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_long . ' ' . $sseo_rd_long . ' ' . $sseo_rd_short( 1, 2 ) . '</p>' ), 'sentence_length' ),
	);
	sseo_check( 'long sentences: 20 words is not long; 1 of 4 good, 1 of 3 and 7 of 20 ok, 2 of 4 bad', array( 'good', 'good', 'ok', 'ok', 'bad' ) === $sseo_vals, $sseo_vals );
	sseo_check( 'long sentences counted', str_contains( $sseo_an_text( $sseo_rd( '<p>' . $sseo_rd_long . ' ' . $sseo_rd_long . ' ' . $sseo_rd_short( 1, 2 ) . '</p>' ), 'sentence_length' ), ': 2 of 4. Split' ) );

	// Long paragraphs: more than 150 words; up to 200 ok.
	$sseo_vals = array();
	foreach ( array( 150, 151, 200, 201 ) as $sseo_count ) {
		$sseo_vals[] = $sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_short( 1, 2 ) . '</p><p>' . $sseo_rd_words( $sseo_count ) . '</p>' ), 'paragraph_length' );
	}
	sseo_check( 'long paragraphs: 150 words good, 151 and 200 ok, 201 bad', array( 'good', 'ok', 'ok', 'bad' ) === $sseo_vals, $sseo_vals );
	sseo_check( 'long paragraphs counted, with the longest', str_contains( $sseo_an_text( $sseo_rd( '<p>' . $sseo_rd_words( 160 ) . '</p><p>' . $sseo_rd_short( 1, 2 ) . '</p><p>' . $sseo_rd_words( 170 ) . '</p>' ), 'paragraph_length' ), ': 2, the longest has 170' ) );
	$sseo_rd_result = $sseo_rd( '<ul><li>' . $sseo_rd_words( 300 ) . '</li></ul>' );
	sseo_check( 'list items are no paragraphs: no check of paragraphs without any', 'none' === $sseo_an_status( $sseo_rd_result, 'paragraph_length' ) && 'bad' === $sseo_an_status( $sseo_rd_result, 'sentence_length' ), $sseo_rd_result );

	// Subheadings: more than 300 words want one; a part of up to 400 ok.
	$sseo_rd_parts = static fn( int $before, int $after ): string => '<p>' . $sseo_rd_words( $before ) . '</p><h2>Підзаголовок</h2><p>' . $sseo_rd_words( $after ) . '</p>';
	$sseo_vals     = array(
		$sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_words( 300 ) . '</p>' ), 'subheadings' ),
		$sseo_an_status( $sseo_rd( '<p>' . $sseo_rd_words( 301 ) . '</p>' ), 'subheadings' ),
		$sseo_an_status( $sseo_rd( $sseo_rd_parts( 200, 300 ) ), 'subheadings' ),
		$sseo_an_status( $sseo_rd( $sseo_rd_parts( 100, 301 ) ), 'subheadings' ),
		$sseo_an_status( $sseo_rd( $sseo_rd_parts( 100, 400 ) ), 'subheadings' ),
		$sseo_an_status( $sseo_rd( $sseo_rd_parts( 401, 100 ) ), 'subheadings' ),
		$sseo_an_status( $sseo_rd( '<h2>На початку</h2><p>' . $sseo_rd_words( 301 ) . '</p>' ), 'subheadings' ),
	);
	sseo_check( 'subheadings: none needed up to 300 words; 301 without any bad; parts of 300 good, of 301 and 400 ok, of 401 bad, before the first one too; one at the start is one', array( 'none', 'bad', 'good', 'ok', 'ok', 'bad', 'ok' ) === $sseo_vals, $sseo_vals );
	sseo_check( 'no subheadings: the words told', str_contains( $sseo_an_text( $sseo_rd( '<p>' . $sseo_rd_words( 301 ) . '</p>' ), 'subheadings' ), '301 words and no subheadings' ) );
	$sseo_rd_result = $sseo_rd( '<table><tr><td>' . $sseo_rd_words( 500 ) . '</td></tr></table><p>' . $sseo_rd_short( 1, 5 ) . '</p>' );
	sseo_check( 'a table is no prose: its words are not counted', 'none' === $sseo_an_status( $sseo_rd_result, 'subheadings' ) && 'good' === $sseo_an_status( $sseo_rd_result, 'sentence_length' ) && str_contains( $sseo_an_text( $sseo_rd_result, 'sentence_length' ), '0 of 5' ), $sseo_rd_result );
	$sseo_rd_result = $sseo_rd( '<table><caption>' . $sseo_rd_words( 400 ) . '</caption><tr><th>' . $sseo_rd_words( 400 ) . '</th></tr></table><pre>' . $sseo_rd_words( 400 ) . '</pre><p>' . $sseo_rd_short( 1, 5 ) . '</p>' );
	sseo_check( 'nor a table caption, a header cell or preformatted text', 'none' === $sseo_an_status( $sseo_rd_result, 'subheadings' ) && str_contains( $sseo_an_text( $sseo_rd_result, 'sentence_length' ), '0 of 5' ), $sseo_rd_result );

	// Sentences in a row that start with the same word.
	$sseo_vals = array();
	foreach ( array(
		'<p>Ми робимо. Ми думаємо. Ми пишемо.</p>',
		'<p>Ми а. Ми б. Ми в. Ми г.</p>',
		'<p>Ми а. МИ б. Ми в.</p>',
		'<p>Ми а.</p><p>Ми б.</p><p>Ми в.</p>',
		'<p>Ми а. Ми б. Ми в. Ви а. Ви б. Ви в.</p>',
		'<p>Ми а. Ми б.</p><h2>Ми</h2><p>Ми в.</p>',
		'<ul><li>Ми а.</li><li>Ми б.</li><li>Ми в.</li></ul>',
		'<ul><li>Ми а. Ми б. Ми в.</li></ul>',
		'<p>Ми а. Ми б.</p><ul><li>Ми в.</li></ul><p>Ми г.</p>',
		'<p>Ми а. Ми б.</p><table><tr><td>Ми в.</td></tr></table><p>Ми г.</p>',
	) as $sseo_html ) {
		$sseo_vals[] = $sseo_an_status( $sseo_rd( $sseo_html ), 'sentence_starts' );
	}
	sseo_check( 'sentence starts: three in a row ok, a longer run once, any case, across paragraphs; two runs bad; a subheading, a list or a table breaks a run, list items do not count', array( 'ok', 'ok', 'ok', 'ok', 'bad', 'good', 'good', 'good', 'good', 'good' ) === $sseo_vals, $sseo_vals );
	$sseo_vals = array( $sseo_an_text( $sseo_rd( '<p>Ми а. Ми б. Ми в. Ви а. Ви б. Ви в.</p>' ), 'sentence_starts' ), $sseo_an_text( $sseo_rd( '<p>Ми а. Ми б. Ми в. Він г. Ми д. Ми е. Ми є.</p>' ), 'sentence_starts' ) );
	sseo_check( 'sentence starts: the words named, each once', str_contains( $sseo_vals[0], ': ми, ви.' ) && 1 === substr_count( $sseo_vals[1], 'ми' ), $sseo_vals );

	$sseo_vals = array( $sseo_rd( '' ), $sseo_rd( '<table><tr><td>' . $sseo_rd_words( 50 ) . '</td></tr></table>' ) );
	sseo_check( 'no text to read: a note and no score', array( 'readability' ) === array_column( $sseo_vals[0]['checks'], 'id' ) && 'info' === $sseo_vals[0]['checks'][0]['status'] && 'none' === $sseo_vals[0]['rating'] && 0 === $sseo_vals[0]['score'] && 'none' === $sseo_vals[1]['rating'], $sseo_vals );

	$sseo_vals = array(
		Simple_SEO_Analysis::score( array( array( 'status' => 'good' ), array( 'status' => 'ok' ), array( 'status' => 'bad' ), array( 'status' => 'info' ) ) ),
		Simple_SEO_Analysis::score( array( array( 'status' => 'info' ) ) ),
		Simple_SEO_Analysis::score( array() ),
	);
	sseo_check( 'the score: points of the checks that count, rating none without any', array( array( 'score' => 50, 'rating' => 'ok' ), array( 'score' => 0, 'rating' => 'none' ), array( 'score' => 0, 'rating' => 'none' ) ) === $sseo_vals, $sseo_vals );
	$sseo_an = Simple_SEO_Analysis::run( get_post( $sseo_an_post ), array( 'content' => $sseo_rd_good ) );
	sseo_check( 'the analysis has the readability of the same text', 100 === $sseo_an['readability']['score'] && 4 === count( $sseo_an['readability']['checks'] ) && 366 === $sseo_an['words'], $sseo_an );

	// Scores kept for the list of posts.
	unset( $GLOBALS['current_screen'] );
	$sseo_sc_post            = (int) wp_insert_post( array( 'post_title' => 'Scored', 'post_content' => '<p>' . $sseo_rd_short( 1, 5 ) . '</p>', 'post_status' => 'publish' ) );
	$sseo['posts']['scored'] = $sseo_sc_post;
	$sseo_sc_meta            = static fn( int $id ) => get_post_meta( $id, Simple_SEO_Scores::META, true );
	sseo_check( 'scores: not taken for a post saved outside the admin and the REST API (an import, WP-CLI)', '' === $sseo_sc_meta( $sseo_sc_post ) );
	set_current_screen( 'edit-post' );
	wp_update_post( array( 'ID' => $sseo_sc_post, 'post_title' => 'Scored in the admin' ) );
	$sseo_an  = Simple_SEO_Analysis::run( get_post( $sseo_sc_post ) );
	$sseo_val = $sseo_sc_meta( $sseo_sc_post );
	sseo_check( 'scores: a post saved in the admin, as saved, with the time it changed', array( 'seo' => $sseo_an['score'], 'readability' => $sseo_an['readability']['score'], 'modified' => get_post( $sseo_sc_post )->post_modified ) === $sseo_val && $sseo_val === Simple_SEO_Scores::get( get_post( $sseo_sc_post ) ), $sseo_val );
	update_post_meta( $sseo_sc_post, Simple_SEO_Scores::META, array( 'modified' => '2001-01-01 00:00:00' ) + $sseo_val );
	sseo_check( 'scores: none for a post that changed since', null === Simple_SEO_Scores::get( get_post( $sseo_sc_post ) ) );
	update_post_meta( $sseo_sc_post, Simple_SEO_Scores::META, (object) $sseo_val );
	sseo_check( 'scores: none from a row that is not theirs', null === Simple_SEO_Scores::get( get_post( $sseo_sc_post ) ) );

	delete_post_meta( $sseo_sc_post, Simple_SEO_Scores::META );
	$_REQUEST['bulk_edit'] = 'Update';
	wp_update_post( array( 'ID' => $sseo_sc_post, 'post_title' => 'Scored by bulk edit' ) );
	unset( $_REQUEST['bulk_edit'] );
	sseo_check( 'scores: not taken by bulk edit', '' === $sseo_sc_meta( $sseo_sc_post ) );
	wp_trash_post( $sseo_sc_post );
	sseo_check( 'scores: not taken for a post put in the trash', '' === $sseo_sc_meta( $sseo_sc_post ) );
	wp_untrash_post( $sseo_sc_post );
	wp_update_post( array( 'ID' => $sseo_sc_post, 'post_status' => 'publish' ) );
	$sseo_sc_private = (int) wp_insert_post( array( 'post_type' => 'sseo_private', 'post_title' => 'No scores here', 'post_status' => 'publish' ) );
	$sseo['posts']['scored_private'] = $sseo_sc_private;
	$sseo_sc_empty   = (int) wp_insert_post( array( 'post_title' => 'Nothing to read', 'post_status' => 'draft' ) );
	$sseo['posts']['scored_empty'] = $sseo_sc_empty;
	$sseo_sc_new = (int) wp_insert_post( array( 'post_title' => 'Auto Draft', 'post_status' => 'auto-draft' ) );
	$sseo['posts']['scored_new'] = $sseo_sc_new;
	Simple_SEO_Analysis::render( get_post( $sseo_sc_new ) );
