		)
	);
	kses_remove_filters(); // Block comments with JSON, as an administrator saves them.
	$sseo['posts']['sc_own'] = (int) wp_insert_post( array( 'post_title' => 'Sc Own', 'post_status' => 'publish', 'post_content' => wp_slash( $sseo_own ) ) );
