	sseo_check( 'the block on the site: a details element for each question that opens to its answer', str_contains( $sseo_html, '<div class="simple-seo-faq wp-block-simple-seo-faq"><details class="simple-seo-faq-item"><summary class="simple-seo-faq-question">Own question?</summary><div class="simple-seo-faq-answer">Own <em>answer</em></div></details></div>' ) && 1 === substr_count( $sseo_html, '<details' ) && ! str_contains( $sseo_html, 'script' ), $sseo_html );
	sseo_check( 'an empty block shows nothing', '' === trim( do_blocks( $sseo_block_of( 'simple-seo/faq', array( 'items' => array( array( 'question' => ' ', 'answer' => 'x' ) ) ) ) ) ) && '' === trim( do_blocks( '<!-- wp:simple-seo/faq /-->' ) ) );
	$sseo_g = $sseo_sc_graph( array( 'p' => $sseo['posts']['sc_own'] ) );
	sseo_check( "the block's questions make a FAQ page whatever its type", array( 'Own question?' ) === array_column( $sseo_sc_node( $sseo_g, 'FAQPage' )['mainEntity'] ?? array(), 'name' ), $sseo_g );
	add_filter( 'simple_seo_faq', static fn( array $items, WP_Post $post, bool $accordions ): array => $post->ID === $sseo['posts']['sc'] && ! $accordions ? array( array( 'question' => '<i>Theme</i> question?', 'answer' => 'Theme answer' ), array( 'question' => 'No answer' ), 'junk' ) : $items, 10, 3 );
	$sseo_faq = Simple_SEO_FAQ::questions( get_post( $sseo['posts']['sc'] ), false );
	remove_all_filters( 'simple_seo_faq' );
	sseo_check( 'simple_seo_faq: a theme gives its own questions, cleaned like the rest', array( array( 'question' => 'Theme question?', 'answer' => 'Theme answer' ) ) === $sseo_faq, $sseo_faq );

	// The SEO block of the editor.
	wp_set_current_user( $sseo_ed );
	$sseo_html = sseo_capture( static fn() => Simple_SEO_Editor::render_meta_box( get_post( $sseo['posts']['sc_faq'] ) ) );
	wp_set_current_user( 0 );
	sseo_check( 'the SEO block: Schema with both types and what the page is now', str_contains( $sseo_html, '>Schema</h4>' ) && str_contains( $sseo_html, 'name="simple_seo[schema_page_type]"' ) && str_contains( $sseo_html, '<option value="" selected=\'selected\'>As set for this post type: Web page</option>' ) && str_contains( $sseo_html, 'name="simple_seo[schema_article_type]"' ) && str_contains( $sseo_html, 'Now: FAQ page with questions and answers: 3' ), $sseo_html );

	// A page's own JSON-LD.
	$sseo_field = Simple_SEO_Fields::get( 'schema_custom' );
	sseo_check( 'own JSON-LD: a field of posts and terms under Schema, for whoever edits the advanced fields', null !== $sseo_field && array( 'post', 'term' ) === $sseo_field['objects'] && 'schema' === $sseo_field['group'] && Simple_SEO_Fields::LEVEL_ADVANCED === $sseo_field['level'] && ! Simple_SEO_Fields::user_can_edit( $sseo_au, 'post', $sseo['posts']['sc'], 'schema_custom' ) && Simple_SEO_Fields::user_can_edit( $sseo_ed, 'post', $sseo['posts']['sc'], 'schema_custom' ) );
	$sseo_json = wp_json_encode( array( '@context' => 'https://schema.org', '@type' => 'Event', 'name' => 'Launch <b>day</b>', 'description' => 'He said "go"' ) );
	sseo_check( 'own JSON-LD is kept as typed, trimmed; too long is nothing', $sseo_json === Simple_SEO_Fields::sanitize_value( 'schema_custom', "  {$sseo_json}\n" ) && '' === Simple_SEO_Fields::sanitize_value( 'schema_custom', str_repeat( 'x', Simple_SEO_Schema::MAX_CUSTOM + 1 ) ) && '' === Simple_SEO_Fields::sanitize_value( 'schema_custom', array( 'no' ) ) );
	$sseo_parsed = array(
		Simple_SEO_Schema::parse_custom( $sseo_json ),
		Simple_SEO_Schema::parse_custom( wp_json_encode( array( array( '@type' => 'Product', 'name' => 'P' ), array( 'name' => 'no type' ), 'junk', array( '@type' => 'Offer' ) ) ) ),
		Simple_SEO_Schema::parse_custom( wp_json_encode( array( '@context' => 'https://schema.org', '@graph' => array( array( '@type' => 'Place', '@context' => 'x' ) ) ) ) ),
		Simple_SEO_Schema::parse_custom( '{"@type": "Event",' ),
		Simple_SEO_Schema::parse_custom( '"text"' ),
		Simple_SEO_Schema::parse_custom( '[1, 2]' ),
		Simple_SEO_Schema::parse_custom( '  ' ),
	);
	sseo_check(
		'own JSON-LD: an object, a list or a document with @graph; nodes with a @type, without @context; what is wrong said',
		array( array( '@type' => 'Event', 'name' => 'Launch <b>day</b>', 'description' => 'He said "go"' ) ) === $sseo_parsed[0]['nodes'] && '' === $sseo_parsed[0]['error']
			&& array( 'Product', 'Offer' ) === array_column( $sseo_parsed[1]['nodes'], '@type' ) && 2 === count( $sseo_parsed[1]['nodes'] )
			&& array( array( '@type' => 'Place' ) ) === $sseo_parsed[2]['nodes']
			&& array() === $sseo_parsed[3]['nodes'] && str_starts_with( $sseo_parsed[3]['error'], 'Not valid JSON: ' )
			&& 'Not a JSON-LD object: a JSON object or a list of them is needed.' === $sseo_parsed[4]['error']
			&& 'No node with a @type: each object of JSON-LD needs one.' === $sseo_parsed[5]['error']
			&& array( 'nodes' => array(), 'error' => '' ) === $sseo_parsed[6],
		$sseo_parsed
	);
	update_post_meta( $sseo['posts']['sc'], Simple_SEO_Fields::meta_key( 'schema_custom' ), wp_slash( wp_json_encode( array( array( '@type' => 'Event', 'name' => 'Close </script><script>alert(1)</script>' ), array( '@type' => 'Product', 'name' => 'P' ) ) ) ) );
	add_filter( 'simple_seo_schema_graph', static fn( array $graph ): array => array_slice( $graph, 0, 1 ) );
	$sseo_g = $sseo_sc_graph( array( 'p' => $sseo['posts']['sc'] ) );
	remove_all_filters( 'simple_seo_schema_graph', 10 );
	sseo_check( "own JSON-LD goes last in the page's graph, past the filters that thin it out", array( 'WebSite', 'Event', 'Product' ) === $sseo_sc_types( $sseo_g ), $sseo_sc_types( $sseo_g ) );
	update_term_meta( $sseo_news, Simple_SEO_Fields::meta_key( 'schema_custom' ), wp_slash( '{"@type":"Place","name":"News room"}' ) );
	$sseo_g = $sseo_sc_graph( array( 'cat' => $sseo_news ) );
	delete_term_meta( $sseo_news, Simple_SEO_Fields::meta_key( 'schema_custom' ) );
	sseo_check( "a term's own JSON-LD in its archive's graph", 'News room' === ( $sseo_sc_node( $sseo_g, 'Place' )['name'] ?? '' ), $sseo_sc_types( $sseo_g ) );
	wp_update_post( array( 'ID' => $sseo['posts']['sc'], 'post_password' => 'secret' ) );
	$sseo_g = Simple_SEO_Schema::graph( Simple_SEO_Context::for_post( get_post( $sseo['posts']['sc'] ) ) );
	wp_update_post( array( 'ID' => $sseo['posts']['sc'], 'post_password' => '' ) );
	sseo_check( 'no own JSON-LD while a password is asked', array() === $sseo_sc_node( $sseo_g, 'Event' ) );

	// Printed in every mode: in the graph, or alone where the graph is not.
	$sseo_sc_query               = $GLOBALS['wp_query'];
	$sseo_sc_actions             = $GLOBALS['wp_actions']['wp'] ?? null;
	$GLOBALS['wp_actions']['wp'] = 1;
	$sseo_sc_printed             = static function () use ( $sseo ): array {
		$GLOBALS['wp_query'] = sseo_query( array( 'p' => $sseo['posts']['sc'] ) );
		Simple_SEO_Context::reset();
		$html = sseo_capture( array( Simple_SEO_Schema::class, 'output' ) );
		$json = preg_match( '~<script type="application/ld\+json" class="simple-seo-schema">(.*)</script>~s', $html, $match ) ? json_decode( $match[1], true ) : null;
		return array( $html, is_array( $json ) ? array_map( static fn( array $node ) => $node['@type'] ?? '', $json['@graph'] ) : null );
	};
	$sseo_sc_out = array( 'auto' => $sseo_sc_printed() );
	update_option( Simple_SEO_Schema::OPTION, array( 'mode' => 'off' ) );
	Simple_SEO_Settings::flush();
	$sseo_sc_out['off'] = $sseo_sc_printed();
	update_option( Simple_SEO_Schema::OPTION, array( 'mode' => 'auto' ) );
	Simple_SEO_Settings::flush();
	add_filter( 'wpseo_json_ld_output', '__return_false' );
	$sseo_sc_out['banned'] = $sseo_sc_printed();
	remove_all_filters( 'wpseo_json_ld_output' );
	add_filter( 'simple_seo_conflicting_plugin', static fn(): string => 'Yoast SEO' );
	$sseo_sc_out['yoast'] = $sseo_sc_printed();
	remove_all_filters( 'simple_seo_conflicting_plugin' );
	delete_post_meta( $sseo['posts']['sc'], Simple_SEO_Fields::meta_key( 'schema_custom' ) );
	update_option( Simple_SEO_Schema::OPTION, array( 'mode' => 'off' ) );
	Simple_SEO_Settings::flush();
	$sseo_sc_out['off_none'] = $sseo_sc_printed();
	delete_option( Simple_SEO_Schema::OPTION );
	Simple_SEO_Settings::flush();
	$GLOBALS['wp_query'] = $sseo_sc_query;
	if ( null === $sseo_sc_actions ) {
		unset( $GLOBALS['wp_actions']['wp'] );
	} else {
		$GLOBALS['wp_actions']['wp'] = $sseo_sc_actions;
	}
	Simple_SEO_Context::reset();
	sseo_check( "own JSON-LD in the graph, or alone in every mode where the graph is not; nothing next to another SEO plugin or without any", 'Event' === ( $sseo_sc_out['auto'][1][ count( $sseo_sc_out['auto'][1] ) - 2 ] ?? '' ) && 'WebSite' === $sseo_sc_out['auto'][1][0] && array( 'Event', 'Product' ) === $sseo_sc_out['off'][1] && array( 'Event', 'Product' ) === $sseo_sc_out['banned'][1] && '' === $sseo_sc_out['yoast'][0] && '' === $sseo_sc_out['off_none'][0], array_map( static fn( array $out ) => $out[1], $sseo_sc_out ) );
	sseo_check( 'own JSON-LD cannot close the script: < and > escaped', 1 === substr_count( $sseo_sc_out['off'][0], '</script>' ) && str_contains( $sseo_sc_out['off'][0], chr( 92 ) . 'u003C/script' . chr( 92 ) . 'u003E' ), $sseo_sc_out['off'][0] );

	// The field in the editor: a code box, and what goes into the graph or what is wrong.
	update_post_meta( $sseo['posts']['sc_faq'], Simple_SEO_Fields::meta_key( 'schema_custom' ), wp_slash( '[{"@type":"Event"},{"@type":["Product","Thing"]}]' ) );
	wp_set_current_user( $sseo_ed );
	$sseo_html = sseo_capture( static fn() => Simple_SEO_Editor::render_meta_box( get_post( $sseo['posts']['sc_faq'] ) ) );
	update_post_meta( $sseo['posts']['sc_faq'], Simple_SEO_Fields::meta_key( 'schema_custom' ), wp_slash( '{"@type": oops}' ) );
	$sseo_html_bad = sseo_capture( static fn() => Simple_SEO_Editor::render_meta_box( get_post( $sseo['posts']['sc_faq'] ) ) );
	wp_set_current_user( 0 );
	delete_post_meta( $sseo['posts']['sc_faq'], Simple_SEO_Fields::meta_key( 'schema_custom' ) );
	sseo_check( 'the editor: a code box with the JSON as typed, the types of its nodes, or what is wrong', str_contains( $sseo_html, '<textarea id="simple-seo-field-schema_custom" name="simple_seo[schema_custom]" rows="8" class="large-text code" spellcheck="false">[{&quot;@type&quot;:&quot;Event&quot;}' ) && str_contains( $sseo_html, 'Now: nodes of the graph: Event; Product, Thing' ) && str_contains( $sseo_html_bad, 'Now: Not valid JSON: Syntax error.' ), $sseo_html_bad );

	// The tab.
	Simple_SEO_Schema::add_admin_tab();
	Simple_SEO_Admin::register_settings();
	wp_set_current_user( $sseo_u['administrator'] );
	update_option( Simple_SEO_Schema::OPTION, array( 'represents' => 'person', 'person' => $sseo_au, 'profiles' => array( 'https://facebook.test/acme' ) ) );
	update_option( Simple_SEO_Schema::NAMES, array( 'name' => 'Acme "Ltd"' ) );
	Simple_SEO_Settings::flush();
	$_GET['tab'] = 'schema';
	$sseo_html   = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	add_filter( 'wpseo_json_ld_output', '__return_false' );
	$sseo_html_off = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	remove_all_filters( 'wpseo_json_ld_output' );
	unset( $_GET['tab'] );
	wp_set_current_user( 0 );
	sseo_check( 'the Schema tab sits between Social networks and Indexing', strpos( $sseo_html, '>Social networks<' ) < strpos( $sseo_html, '>Schema<' ) && strpos( $sseo_html, '>Schema<' ) < strpos( $sseo_html, '>Indexing<' ) );
	sseo_check( 'the tab: the modes with Auto chosen, whom the site represents with its user, the names, the logo, the profiles, breadcrumbs', str_contains( $sseo_html, 'name="simple_seo_schema[mode]" value="auto"  checked=\'checked\'' ) && str_contains( $sseo_html, 'name="simple_seo_schema[represents]" value="person"  checked=\'checked\'' ) && (bool) preg_match( '~<select name=\'simple_seo_schema\[person\]\'[^>]*>.*<option value=\'' . $sseo_au . '\' selected=\'selected\'>~s', $sseo_html ) && str_contains( $sseo_html, 'name="simple_seo_schema_names[name]" value="Acme &quot;Ltd&quot;"' ) && str_contains( $sseo_html, 'name="simple_seo_schema[logo]"' ) && str_contains( $sseo_html, ">https://facebook.test/acme</textarea>" ) && str_contains( $sseo_html, 'name="simple_seo_schema[breadcrumbs]" value="1"  checked=\'checked\'' ) );
	sseo_check( 'the tab shows the graph of the home page', str_contains( $sseo_html, 'class="simple-seo-schema-example"' ) && str_contains( $sseo_html, '&quot;@type&quot;: &quot;WebSite&quot;' ) );
	sseo_check( 'a theme that switches off the graph of SEO plugins is named on the tab', ! str_contains( $sseo_html, 'wpseo_json_ld_output' ) && str_contains( $sseo_html_off, 'The active theme switches off the graph of SEO plugins' ) );
	sseo_check( 'the tab saves both rows', 'simple-seo-schema' === ( get_registered_settings()[ Simple_SEO_Schema::OPTION ]['group'] ?? '' ) && 'simple-seo-schema' === ( get_registered_settings()[ Simple_SEO_Schema::NAMES ]['group'] ?? '' ) );
	update_option( Simple_SEO_Schema::OPTION, array( 'page_types' => array( 'page' => 'AboutPage' ), 'article_types' => array( 'page' => 'BlogPosting' ) ) );
	Simple_SEO_Settings::flush();
	wp_set_current_user( $sseo_u['administrator'] );
	$_GET['tab'] = 'schema';
	$sseo_html   = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	unset( $_GET['tab'] );
	wp_set_current_user( 0 );
	$sseo_chosen = static fn( string $name ): string => preg_match( '~<select[^>]*name="simple_seo_schema\[' . preg_quote( $name, '~' ) . '\]">.*?<option value="([^"]*)" selected=\'selected\'>~s', $sseo_html, $sseo_match ) ? $sseo_match[1] : '';
	sseo_check( 'the tab: a type of page and of article for each post type, as saved or Simple SEO\'s own', 'AboutPage' === $sseo_chosen( 'page_types][page' ) && 'WebPage' === $sseo_chosen( 'page_types][post' ) && 'BlogPosting' === $sseo_chosen( 'article_types][page' ) && 'Article' === $sseo_chosen( 'article_types][post' ) && 'None' === $sseo_chosen( 'article_types][sseo_map' ), array( $sseo_chosen( 'page_types][page' ), $sseo_chosen( 'article_types][page' ), $sseo_chosen( 'article_types][post' ) ) );
	delete_option( Simple_SEO_Schema::OPTION );
	delete_option( Simple_SEO_Schema::NAMES );
	Simple_SEO_Settings::flush();

	if ( Simple_SEO_WP_Loc::languages() ) {
		$sseo_d = Simple_SEO_WP_Loc::default_language();
		$sseo_o = (string) current( array_diff( Simple_SEO_WP_Loc::codes(), array( $sseo_d ) ) );
		update_option( Simple_SEO_Schema::NAMES, array( 'name' => 'Acme default' ) );
		update_option( Simple_SEO_Schema::NAMES . '_' . $sseo_o, array( 'name' => 'Acme other' ) );
		Simple_SEO_Settings::flush();
		$sseo_g      = Simple_SEO_WP_Loc::in_language( $sseo_o, static fn() => Simple_SEO_Schema::graph( Simple_SEO_Context::for_post( get_post( $sseo['posts']['bc_ml_o'] ) ) ) );
		$sseo_prefix = '/' . WP_LOC_DB::from_db_language_code( $sseo_o ) . '/';
		$sseo_lang   = Simple_SEO_WP_Loc::in_language( $sseo_o, static fn() => get_bloginfo( 'language' ) );
		delete_option( Simple_SEO_Schema::NAMES . '_' . $sseo_o );
		Simple_SEO_Settings::flush();
		// home_url() takes the language prefix on the site only (after template_redirect), not here.
		sseo_check( "wp-loc: a translation's graph in its language: the names of its row, its address and the language of the page", 'Acme other' === ( $sseo_sc_node( $sseo_g, 'Organization' )['name'] ?? '' ) && str_contains( $sseo_sc_node( $sseo_g, 'WebPage' )['url'], $sseo_prefix ) && $sseo_lang === $sseo_sc_node( $sseo_g, 'WebPage' )['inLanguage'] && str_replace( '_', '-', Simple_SEO_WP_Loc::locale_of( $sseo_o ) ) === $sseo_lang, $sseo_g );
		sseo_check( "wp-loc: the default language keeps its own names", 'Acme default' === ( $sseo_sc_node( Simple_SEO_Schema::graph( Simple_SEO_Context::for_post( get_post( $sseo['posts']['bc_ml_d'] ) ) ), 'Organization' )['name'] ?? '' ) );
		delete_option( Simple_SEO_Schema::NAMES );
		Simple_SEO_Settings::flush();
	} else {
		echo "  skip  Schema with wp-loc (tools/wp-loc-it.sh runs these checks)\n";
	}
	if ( false !== $sseo_sc_icon ) {
		update_option( 'site_icon', $sseo_sc_icon );
	}
	if ( false !== $sseo_sc_logo ) {
		set_theme_mod( 'custom_logo', $sseo_sc_logo );
	}

	// ------------------------------------------------------------------------------------------
	sseo_section( 'Local SEO' );

	require_once SIMPLE_SEO_DIR . 'includes/class-simple-seo-import-source.php';
	$sseo_lc_theme_keys = array( 'schema_org_type', 'schema_org_email', 'schema_org_phone', 'schema_org_street', 'schema_org_city', 'schema_org_postal_code', 'schema_org_country', 'schema_org_description', 'schema_org_name', 'schema_org_alternate_name', 'schema_org_legal_name', 'schema_org_area_served', 'options_opening_hours', 'options_footer_phone', 'options_footer_email' );
	$sseo_lc_clear      = static function () use ( $sseo_lc_theme_keys ): void {
		foreach ( array_merge( array( Simple_SEO_Local::OPTION, Simple_SEO_Local::NAMES, Simple_SEO_Schema::OPTION, Simple_SEO_Schema::NAMES ), $sseo_lc_theme_keys ) as $sseo_name ) {
			delete_option( $sseo_name );
		}
		Simple_SEO_Settings::flush();
	};
	$sseo_lc_clear();
	$sseo_lc_org = static fn(): array => (array) Simple_SEO_Schema::publisher();
	$sseo_lc_set = static function ( array $local, array $names = array() ): void {
		update_option( Simple_SEO_Local::OPTION, Simple_SEO_Local::sanitize( $local ) );
		update_option( Simple_SEO_Local::NAMES, Simple_SEO_Local::sanitize_names( $names ) );
		Simple_SEO_Settings::flush();
	};
	$sseo_lc_details = array( 'description', 'address', 'telephone', 'email', 'areaServed', 'geo', 'hasMap', 'openingHoursSpecification', 'priceRange' );

	sseo_check( 'the defaults: an organization without details', array( 'type' => 'Organization', 'phone' => '', 'email' => '', 'postal_code' => '', 'country' => '', 'geo' => '', 'map' => '', 'hours' => array() ) === Simple_SEO_Settings::get( Simple_SEO_Local::OPTION ) && array( 'description' => '', 'street' => '', 'locality' => '', 'region' => '', 'area_served' => '', 'price_range' => '' ) === Simple_SEO_Settings::get( Simple_SEO_Local::NAMES ) );
	sseo_check( 'the texts are kept per language, the rest is common', in_array( Simple_SEO_Local::NAMES, Simple_SEO_Settings::localized(), true ) && ! in_array( Simple_SEO_Local::OPTION, Simple_SEO_Settings::localized(), true ) );
	$sseo_n = $sseo_lc_org();
	sseo_check( 'without details the organization is as it was: an Organization with its @id, no details', 'Organization' === $sseo_n['@type'] && home_url( '/' ) . '#organization' === $sseo_n['@id'] && ! array_intersect( $sseo_lc_details, array_keys( $sseo_n ) ), $sseo_n );

	// The settings.
	$sseo_clean = Simple_SEO_Local::sanitize( array( 'type' => 'Spaceship', 'phone' => 'call 12-34', 'email' => 'not an email', 'postal_code' => ' <b>01001</b>' . str_repeat( '9', 30 ), 'country' => 'Ukraine', 'geo' => '91, 30', 'map' => 'javascript:alert(1)', 'hours' => 'no' ) );
	sseo_check( 'sanitized: an unknown type is an organization; a phone of few digits, a wrong e-mail, coordinates out of range, a map that is no address and hours that are no list are nothing; a country by name stays', array( 'type' => 'Organization', 'phone' => '', 'email' => '', 'postal_code' => '01001' . str_repeat( '9', 15 ), 'country' => 'Ukraine', 'geo' => '', 'map' => '', 'hours' => array() ) === $sseo_clean, $sseo_clean );
