		do_action( 'wpml_set_element_language_details', array( 'element_id' => $sseo['posts']['gc_other'], 'element_type' => 'post_post', 'trid' => null, 'language_code' => $sseo_o, 'source_language_code' => null ) );
		clean_post_cache( $sseo['posts']['gc_other'] );
