	foreach ( (array) $GLOBALS['wpdb']->get_col( "SELECT option_name FROM {$GLOBALS['wpdb']->options} WHERE option_name LIKE '\\_transient\\_simple\\_seo\\_gsc\\_%'" ) as $sseo_name ) { // phpcs:ignore WordPress.DB.DirectDatabaseQuery
