		if ( Simple_SEO_IndexNow::ENDPOINT !== $url ) {
			return $pre;
		}
		$GLOBALS['sseo_ix_requests'][] = array( (string) $url, $args );

		return $sseo_ix_answer( (string) $url, $args );
