	Simple_SEO_IndexNow::add( array( 'ftp://example.com/x', '', 'javascript:alert(1)', 'https://www.example.com/a/' ) );
	sseo_check( 'only web addresses wait', array( 'https://www.example.com/a/' => true ) === Simple_SEO_IndexNow::queue()['urls'] );
