	$GLOBALS['sseo_ix_requests'] = array();
	$sseo_ix_run();
	$sseo_bodies = array_map( static fn( array $request ): array => (array) json_decode( (string) $request[1]['body'], true ), $GLOBALS['sseo_ix_requests'] );
