			&& '@rmsite' === get_option( Simple_SEO_Social::OPTION )['x_account'] && '' === Simple_SEO_Files::robots_option() && ! isset( $sseo_rm_again['settings']['robots_txt'] ) && ! isset( $sseo_rm_again['left']['url_bases'] ),
