		array( 'title' => '{title} {sep} {site}', 'description' => 'Desc here', 'og_title' => 'OG {title}', 'og_image' => (string) $sseo_og, 'index' => 'noindex', 'nofollow' => '1', 'canonical' => 'https://example.com/ai-one/', 'primary_category' => (string) $sseo_news, 'keyphrase' => 'one', 'keyphrases' => "two\nтри слова" ) === $sseo_ai_fields,
		$sseo_ai_fields
	);
	sseo_check( "Simple SEO's own field stays; its own robots without noindex is index; an image elsewhere is not taken; an image AIOSEO did not pick itself is not taken", 'Own two' === Simple_SEO_Fields::post_value( $sseo_ai_2, 'title' ) && 'index' === Simple_SEO_Fields::post_value( $sseo_ai_2, 'index' ) && '' === Simple_SEO_Fields::post_value( $sseo_ai_2, 'nofollow' ) && '' === Simple_SEO_Fields::post_value( $sseo_ai_2, 'og_image' ) && 'Three' === Simple_SEO_Fields::post_value( $sseo['posts']['ai_3'], 'title' ) && '' === Simple_SEO_Fields::post_value( $sseo['posts']['ai_3'], 'og_image' ) );
	sseo_check( 'a page: its title, no primary category; a post type without SEO fields is left alone', 'Page T' === Simple_SEO_Fields::post_value( $sseo['posts']['ai_page'], 'title' ) && '' === Simple_SEO_Fields::post_value( $sseo['posts']['ai_page'], 'primary_category' ) && '' === Simple_SEO_Fields::post_value( $sseo['posts']['ai_menu'], 'title' ) );
	$sseo_vals = array();
	foreach ( array( $sseo_ai_2, $sseo['posts']['ai_3'], $sseo['posts']['ai_kw'], $sseo['posts']['ai_fk'], $sseo['posts']['ai_add'] ) as $sseo_id ) {
		$sseo_vals[] = array( Simple_SEO_Fields::post_value( $sseo_id, 'keyphrase' ), Simple_SEO_Fields::post_value( $sseo_id, 'keyphrases' ) );
	}
	sseo_check(
		"Simple SEO's own focus keyphrase stays; each column falls back on the older JSON on its own; older rows' keyphrases; the focus keyword alone; the additional keywords alone",
		array( array( 'Own ai focus', 'two more' ), array( 'three focus', '' ), array( 'Own kw focus', 'ключ' ), array( 'фокус', '' ), array( '', 'слово' ) ) === $sseo_vals,
		$sseo_vals
	);
	sseo_check( 'the report of the posts', array( 'seen' => 7, 'fields' => 18, 'changed' => 7, 'kept' => 2, 'refused' => 1 ) == $sseo_ai_report['post'] && array( 'page_number' => 1, 'post_modified_date' => 1 ) == $sseo_ai_report['dropped'], $sseo_ai_report ); // phpcs:ignore Universal.Operators.StrictComparisons
	sseo_check( "AIOSEO's rows are left as they were", $sseo_ai_rows === (int) $sseo_ai_db->get_var( "SELECT COUNT(*) FROM `{$sseo_ai_posts}`" ) && 'Ai two' === $sseo_ai_db->get_var( $sseo_ai_db->prepare( "SELECT title FROM `{$sseo_ai_posts}` WHERE post_id = %d", $sseo_ai_2 ) ) );

	// Terms, from the table of AIOSEO Pro.
	$sseo_ai_report = array();
	$sseo_ai_next   = Simple_SEO_Aioseo_Import::terms( 0, 2, $sseo_ai_report );
	$sseo_ai_steps  = array( $sseo_ai_next );
	while ( $sseo_ai_next && count( $sseo_ai_steps ) < 10 ) {
		$sseo_ai_next    = Simple_SEO_Aioseo_Import::terms( $sseo_ai_next, 2, $sseo_ai_report );
		$sseo_ai_steps[] = $sseo_ai_next;
	}
	sseo_check( 'terms in batches, by ID', array( $sseo_ai_t['cat'], $sseo_ai_t['fmt'], 99999999, 0 ) === $sseo_ai_steps, $sseo_ai_steps );
	$sseo_ai_fields = array();
	foreach ( array( 'title', 'description', 'index', 'nofollow', 'canonical' ) as $sseo_key ) {
		$sseo_ai_fields[ $sseo_key ] = Simple_SEO_Fields::term_value( $sseo_ai_t['cat'], $sseo_key );
	}
	sseo_check( "a term's fields: #taxonomy_title is the term's own title, its robots, canonical; columns the table lacks are skipped", array( 'title' => '{title} best {sep} {site}', 'description' => 'Cat desc', 'index' => 'noindex', 'nofollow' => '', 'canonical' => 'https://example.com/ai-cat/' ) === $sseo_ai_fields, $sseo_ai_fields );
	sseo_check( "Simple SEO's own field stays; terms that are gone, or of a taxonomy without SEO fields, are left alone", 'Own cat two' === Simple_SEO_Fields::term_value( $sseo_ai_t['cat2'], 'title' ) && 'Tag desc' === Simple_SEO_Fields::term_value( $sseo_ai_t['tag'], 'description' ) && '' === Simple_SEO_Fields::term_value( $sseo_ai_t['fmt'], 'title' ) );
	sseo_check( 'the report of the terms; a keyphrase of a term is no field', array( 'seen' => 3, 'fields' => 5, 'changed' => 2, 'kept' => 1 ) == $sseo_ai_report['term'] && ! metadata_exists( 'term', $sseo_ai_t['cat'], Simple_SEO_Fields::meta_key( 'keyphrase' ) ), $sseo_ai_report ); // phpcs:ignore Universal.Operators.StrictComparisons
	sseo_check( 'what Simple SEO has nothing for, by posts', array( 'twitter' => 1, 'schema' => 1 ) == Simple_SEO_Aioseo_Import::left(), Simple_SEO_Aioseo_Import::left() ); // phpcs:ignore Universal.Operators.StrictComparisons

	// The whole run.
	Simple_SEO_Import::start( 'aioseo' );
	$sseo_ai_count = 0;
	do {
		$sseo_ai_state = Simple_SEO_Import::run( 'aioseo', 0.0 );
		++$sseo_ai_count;
	} while ( 'running' === $sseo_ai_state['status'] && $sseo_ai_count < 20 );
	sseo_check( 'a run of zero seconds still takes one batch, and goes on from where it stopped', 'done' === $sseo_ai_state['status'] && 5 === $sseo_ai_count, array( $sseo_ai_count, $sseo_ai_state['status'] ) );
	sseo_check( "run again: everything is Simple SEO's already, kept", ! isset( $sseo_ai_state['report']['settings'] ) && 0 === ( $sseo_ai_state['report']['post']['fields'] ?? 0 ) && 20 === $sseo_ai_state['report']['post']['kept'] && 6 === $sseo_ai_state['report']['term']['kept'] && 1 === $sseo_ai_state['report']['left']['robots_rules'] && 1 === $sseo_ai_state['report']['left']['schema'], $sseo_ai_state['report'] );

	// The admin.
	wp_set_current_user( $sseo_u['administrator'] );
	Simple_SEO_Import::add_admin_tab();
	foreach ( Simple_SEO_Import::SOURCES as $sseo_class ) {
		update_option( $sseo_class::STATE, array( 'status' => 'pending' ) );
	}
	set_current_screen( 'dashboard' );
	$sseo_html = sseo_capture( array( Simple_SEO_Import::class, 'notice' ) );
	sseo_check( 'the notice names every plugin with data to import', str_contains( $sseo_html, 'Simple SEO found the data of Yoast SEO, Rank Math, and All in One SEO on this site' ), $sseo_html );
	set_current_screen( 'toplevel_page_' . Simple_SEO_Admin::PAGE );
	$_GET['tab'] = 'import';
	$sseo_html   = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	sseo_check( 'the tab: All in One SEO with what was found and its button', str_contains( $sseo_html, '<h2>All in One SEO</h2>' ) && str_contains( $sseo_html, 'Import from All in One SEO' ) && str_contains( $sseo_html, 'AIOSEO&#039;s #tags become' ) && str_contains( $sseo_html, 'posts with SEO fields: 8' ) && str_contains( $sseo_html, 'name="simple_seo_source" value="aioseo"' ), $sseo_html );
	update_option( Simple_SEO_Aioseo_Import::STATE, array( 'status' => 'done', 'finished' => time(), 'report' => array( 'dropped' => array( 'page_number' => 2 ), 'left' => array( 'robots_rules' => 1 ) ) ) );
	$sseo_html = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	unset( $_GET['tab'], $GLOBALS['current_screen'] );
	wp_set_current_user( 0 );
	sseo_check( "after a run: AIOSEO's tags as AIOSEO writes them, and the rules of robots.txt", str_contains( $sseo_html, '#page_number (2)' ) && str_contains( $sseo_html, 'the rules added to robots.txt' ), $sseo_html );
	update_option( Simple_SEO_Aioseo_Import::STATE, $sseo_ai_state );
	foreach ( array( Simple_SEO_Yoast_Import::STATE, Simple_SEO_Rank_Math_Import::STATE ) as $sseo_name ) {
		delete_option( $sseo_name );
	}

	// The table of AIOSEO 4, before its keyword columns.
	$sseo_ai_db->query( "ALTER TABLE `{$sseo_ai_posts}` DROP COLUMN focus_keyword, DROP COLUMN additional_keywords" );
	sseo_check( 'a table of AIOSEO 4, without the keyword columns: posts found by the rest, keyphrases by the older JSON', 6 === Simple_SEO_Aioseo_Import::summary()['posts'], Simple_SEO_Aioseo_Import::summary() );

	// ------------------------------------------------------------------------------------------
	sseo_section( 'AIOSEO clean-up' );

	// AIOSEO's leftovers: those of the import section and these.
	$sseo_ai_db->query( "CREATE TABLE IF NOT EXISTS `{$sseo_ai_db->prefix}aioseo_cache` ( id BIGINT NOT NULL PRIMARY KEY )" );
	$sseo_ai_db->query( "CREATE TABLE IF NOT EXISTS `{$sseo_ai_db->prefix}sseo_aioseo_keep` ( id INT NOT NULL PRIMARY KEY )" );
	update_option( 'aioseo_options_internal', wp_json_encode( array( 'internal' => array( 'lastActiveVersion' => '5.0.5.1' ) ) ) );
	update_option( 'aioseo_migrations_log', 'x' );
	update_option( 'sseo_aioseo_keep', 'x' );
	set_transient( 'aioseo_sseo', 'x', HOUR_IN_SECONDS );
	wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'aioseo_sseo_daily' );
	wp_schedule_single_event( time() + 2 * HOUR_IN_SECONDS, 'aioseo_sseo_once', array( 1 ) );
	wp_schedule_single_event( time() + 2 * HOUR_IN_SECONDS, 'aioseo_sseo_once', array( 2 ) );
	wp_schedule_single_event( time() + 2 * HOUR_IN_SECONDS, 'sseo_keep_hook' );
	get_role( 'administrator' )->add_cap( 'aioseo_manage_seo' );
	get_role( 'editor' )->add_cap( 'aioseo_page_analysis' );
	get_role( 'editor' )->add_cap( 'sseo_keep_cap' );
	$sseo_ac_user = (int) $sseo_u['administrator'];
	update_user_meta( $sseo_ac_user, '_aioseo_plugin_review_dismissed', '1' );
	update_user_meta( $sseo_ac_user, 'aioseo_sseo', 'x' );
	update_user_meta( $sseo_ac_user, 'sseo_keep', 'x' );
	update_post_meta( $sseo_ai_1, 'sseo_keep', 'x' );
	// AIOSEO's copies of the fields in post meta: one batch and one row more.
	update_post_meta( $sseo_ai_1, '_aioseo_title', '#post_title #separator_sa #site_title' );
	$sseo_ai_db->query( "INSERT INTO {$sseo_ai_db->postmeta} ( post_id, meta_key, meta_value ) VALUES " . implode( ',', array_map( static fn( int $i ): string => "( {$sseo_ai_1}, '_aioseo_filler_{$i}', 'x' )", range( 1, Simple_SEO_Aioseo_Cleanup::BATCH ) ) ) );
	wp_cache_delete( $sseo_ai_1, 'post_meta' );
	$sseo_ac_tables  = (array) $sseo_ai_db->get_col( $sseo_ai_db->prepare( 'SHOW TABLES LIKE %s', $sseo_ai_db->esc_like( $sseo_ai_db->prefix . 'aioseo_' ) . '%' ) );
	$sseo_ac_options = (int) $sseo_ai_db->get_var( "SELECT COUNT(*) FROM {$sseo_ai_db->options} WHERE option_name LIKE 'aioseo\\_%' OR option_name LIKE '\\_transient\\_%aioseo%'" ) - 2;

	// When it may run.
	$sseo_ac_active = static fn( $plugins ): array => array_merge( (array) $plugins, array( 'all-in-one-seo-pack/all_in_one_seo_pack.php' ) );
	update_option( Simple_SEO_Aioseo_Import::STATE, array( 'status' => 'pending' ) );
	$sseo_vals = array( Simple_SEO_Aioseo_Cleanup::blocked() );
	update_option( Simple_SEO_Aioseo_Import::STATE, array( 'status' => 'done' ) );
	$sseo_vals[] = Simple_SEO_Aioseo_Cleanup::blocked();
	add_filter( 'option_active_plugins', $sseo_ac_active );
	$sseo_vals[] = Simple_SEO_Aioseo_Cleanup::blocked();
	remove_filter( 'option_active_plugins', $sseo_ac_active );
	sseo_check( 'only after the import, and never while AIOSEO is active', array( 'import', '', 'active' ) === $sseo_vals, $sseo_vals );

	// What is left.
	$sseo_ac_parts = Simple_SEO_Aioseo_Cleanup::preview();
	sseo_check(
		"what is left of AIOSEO's, by part: tables, the rest of its options with its tasks and the capabilities of roles, settings, user and post meta",
		array( 'tables', 'internals', 'settings', 'usermeta', 'postmeta' ) === array_keys( $sseo_ac_parts ) && count( $sseo_ac_tables ) === $sseo_ac_parts['tables']['rows'] && 2 === $sseo_ac_parts['settings']['rows'] && 2 === $sseo_ac_parts['usermeta']['rows'] && Simple_SEO_Aioseo_Cleanup::BATCH + 1 === $sseo_ac_parts['postmeta']['rows'] && $sseo_ac_options + 3 + 2 === $sseo_ac_parts['internals']['rows'],
		array( $sseo_ac_parts, $sseo_ac_options )
	);
	$sseo_ac_theme = get_theme_root() . '/sseo-ac-theme';
	wp_mkdir_p( $sseo_ac_theme . '/inc' );
	file_put_contents( $sseo_ac_theme . '/inc/seo.php', "<?php \$row = \$wpdb->get_row( \"SELECT title FROM {\$wpdb->prefix}aioseo_posts\" ); \$t = get_post_meta( 1, '_aioseo_title', true );" );
	file_put_contents( $sseo_ac_theme . '/inc/schema.php', "<?php \$o = json_decode( get_option( 'aioseo_options' ), true );" );
	$sseo_ac_dir = static fn(): string => $sseo_ac_theme;
	add_filter( 'stylesheet_directory', $sseo_ac_dir );
	$sseo_vals = Simple_SEO_Aioseo_Cleanup::theme_reads( array( 'tables', 'internals', 'settings', 'usermeta', 'postmeta' ) );
	sseo_check( "the active theme's files that read AIOSEO's tables, settings or post meta", array( 'tables' => array( 'sseo-ac-theme/inc/seo.php' ), 'settings' => array( 'sseo-ac-theme/inc/schema.php' ), 'postmeta' => array( 'sseo-ac-theme/inc/seo.php' ) ) == $sseo_vals, $sseo_vals ); // phpcs:ignore Universal.Operators.StrictComparisons

	// The page and the form.
	wp_set_current_user( $sseo_ac_user );
	set_current_screen( 'toplevel_page_' . Simple_SEO_Admin::PAGE );
	$_GET['tab'] = 'import';
	$sseo_html   = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	sseo_check(
		"the tab offers AIOSEO's parts; what the theme reads is unticked",
		str_contains( $sseo_html, 'Remove the data of All in One SEO' ) && str_contains( $sseo_html, 'AIOSEO&#039;s copies of the fields of posts' ) && (bool) preg_match( '/value="tables"\s*\/>/', $sseo_html ) && (bool) preg_match( '/value="usermeta"\s+checked=\'checked\'/', $sseo_html ) && str_contains( $sseo_html, 'id="simple-seo-cleanup-aioseo"' ),
		$sseo_html
	);
	remove_filter( 'stylesheet_directory', $sseo_ac_dir );
	$sseo_vals = array(
		Simple_SEO_Import::act( 'clean', array( 'simple_seo_source' => 'aioseo', 'simple_seo_groups' => array( 'tables' ) ) ),
		Simple_SEO_Import::act( 'clean', array( 'simple_seo_source' => 'aioseo', 'simple_seo_groups' => array( 'termmeta' ), 'simple_seo_backup' => '1' ) ),
	);
	sseo_check( 'refused without a backup, and without a part AIOSEO has', array( 'backup', 'groups' ) === $sseo_vals && array() === Simple_SEO_Aioseo_Cleanup::state(), $sseo_vals );

	// A run.
	$sseo_vals = array( get_post_meta( $sseo_ai_1, '_aioseo_title', true ), get_user_meta( $sseo_ac_user, 'aioseo_sseo', true ) );
	Simple_SEO_Aioseo_Cleanup::start( array( 'tables', 'internals', 'usermeta', 'postmeta' ) );
	$sseo_ac_steps = 0;
	do {
		$sseo_ac_state = Simple_SEO_Aioseo_Cleanup::run( 0.0 );
		++$sseo_ac_steps;
		if ( 4 === $sseo_ac_steps ) {
			$sseo_ac_batch = (int) $sseo_ai_db->get_var( "SELECT COUNT(*) FROM {$sseo_ai_db->postmeta} WHERE meta_key LIKE '\\_aioseo\\_%'" );
		}
	} while ( 'running' === $sseo_ac_state['status'] && $sseo_ac_steps < 20 );
	sseo_check( 'one step per part, the post meta in batches', 'done' === $sseo_ac_state['status'] && 5 === $sseo_ac_steps && 1 === $sseo_ac_batch, array( $sseo_ac_steps, $sseo_ac_batch ) );
	$sseo_ac_caps = array();
	foreach ( wp_roles()->role_objects as $sseo_role ) {
		foreach ( array_keys( (array) $sseo_role->capabilities ) as $sseo_name ) {
			if ( str_starts_with( (string) $sseo_name, 'aioseo_' ) ) {
				$sseo_ac_caps[] = $sseo_name;
			}
		}
	}
	$sseo_ac_left = array(
		'tables'   => (array) $sseo_ai_db->get_col( $sseo_ai_db->prepare( 'SHOW TABLES LIKE %s', $sseo_ai_db->esc_like( $sseo_ai_db->prefix . 'aioseo_' ) . '%' ) ),
		'options'  => (array) $sseo_ai_db->get_col( "SELECT option_name FROM {$sseo_ai_db->options} WHERE option_name LIKE 'aioseo\\_%' OR option_name LIKE '\\_transient\\_%aioseo%'" ),
		'caps'     => $sseo_ac_caps,
		'usermeta' => (int) $sseo_ai_db->get_var( "SELECT COUNT(*) FROM {$sseo_ai_db->usermeta} WHERE meta_key LIKE '\\_aioseo%' OR meta_key LIKE 'aioseo%'" ),
		'postmeta' => (int) $sseo_ai_db->get_var( "SELECT COUNT(*) FROM {$sseo_ai_db->postmeta} WHERE meta_key LIKE '\\_aioseo\\_%'" ),
	);
	sort( $sseo_ac_left['options'] );
	sseo_check( "AIOSEO's tables, other options, tasks, capabilities and meta are gone; its settings stay, as they were not ticked", array( 'tables' => array(), 'options' => array( 'aioseo_options', 'aioseo_options_dynamic' ), 'caps' => array(), 'usermeta' => 0, 'postmeta' => 0 ) === $sseo_ac_left && false === get_transient( 'aioseo_sseo' ) && false === wp_next_scheduled( 'aioseo_sseo_daily' ) && false === wp_next_scheduled( 'aioseo_sseo_once', array( 2 ) ), $sseo_ac_left );
	sseo_check(
		'what is not AIOSEO\'s stays, Simple SEO\'s imported fields included',
		'x' === get_option( 'sseo_aioseo_keep' ) && (bool) wp_next_scheduled( 'sseo_keep_hook' ) && get_role( 'editor' )->has_cap( 'sseo_keep_cap' ) && 'x' === get_user_meta( $sseo_ac_user, 'sseo_keep', true ) && 'x' === get_post_meta( $sseo_ai_1, 'sseo_keep', true )
			&& '{title} {sep} {site}' === Simple_SEO_Fields::post_value( $sseo_ai_1, 'title' ) && 'Cat desc' === Simple_SEO_Fields::term_value( $sseo_ai_t['cat'], 'description' )
			&& array( $sseo_ai_db->prefix . 'sseo_aioseo_keep' ) === $sseo_ai_db->get_col( $sseo_ai_db->prepare( 'SHOW TABLES LIKE %s', $sseo_ai_db->esc_like( $sseo_ai_db->prefix . 'sseo_aioseo_keep' ) ) )
	);
	sseo_check( 'the cached meta of the posts and users goes too', array( '#post_title #separator_sa #site_title', 'x' ) === $sseo_vals && '' === get_post_meta( $sseo_ai_1, '_aioseo_title', true ) && '' === get_user_meta( $sseo_ac_user, 'aioseo_sseo', true ) );
	sseo_check( 'the report counts what went', array( 'tables' => count( $sseo_ac_tables ), 'options' => $sseo_ac_options, 'cron' => 3, 'caps' => 2, 'usermeta' => 2, 'postmeta' => Simple_SEO_Aioseo_Cleanup::BATCH + 1 ) == $sseo_ac_state['report'], $sseo_ac_state['report'] ); // phpcs:ignore Universal.Operators.StrictComparisons
	sseo_check( 'without its table, nothing of AIOSEO is found of posts and terms', array( 'settings' => true, 'posts' => 0, 'terms' => 0 ) === Simple_SEO_Aioseo_Import::summary() && array() === Simple_SEO_Aioseo_Import::left() );
	$sseo_vals = Simple_SEO_Import::act( 'clean', array( 'simple_seo_source' => 'aioseo', 'simple_seo_groups' => array( 'settings' ), 'simple_seo_backup' => '1' ) );
	$sseo_html = sseo_capture( array( Simple_SEO_Admin::class, 'render_page' ) );
	unset( $_GET['tab'], $GLOBALS['current_screen'] );
	wp_set_current_user( 0 );
	sseo_check( 'the settings, on their own; then nothing is left, and the report', '' === $sseo_vals && 2 === Simple_SEO_Aioseo_Cleanup::state()['report']['settings'] && array() === Simple_SEO_Aioseo_Cleanup::preview() && str_contains( $sseo_html, 'No data of All in One SEO is left on this site.' ) && str_contains( $sseo_html, 'Removed: rows of settings: 2.' ), $sseo_html );

	$sseo_ai_db->query( "DROP TABLE IF EXISTS `{$sseo_ai_db->prefix}sseo_aioseo_keep`" );
	delete_option( 'sseo_aioseo_keep' );
	wp_clear_scheduled_hook( 'sseo_keep_hook' );
	get_role( 'editor' )->remove_cap( 'sseo_keep_cap' );
	delete_user_meta( $sseo_ac_user, 'sseo_keep' );
	foreach ( array( '/inc/seo.php', '/inc/schema.php', '/inc', '' ) as $sseo_name ) {
		$sseo_name = $sseo_ac_theme . $sseo_name;
		is_dir( $sseo_name ) ? rmdir( $sseo_name ) : unlink( $sseo_name );
	}
	foreach ( array_merge( $sseo_yi_rows, array( Simple_SEO_Aioseo_Import::STATE, Simple_SEO_Aioseo_Cleanup::OPTION ) ) as $sseo_name ) {
		delete_option( $sseo_name );
	}
	Simple_SEO_Settings::install();
	Simple_SEO_Settings::flush();
	unregister_taxonomy( 'sseo_ai_shelf' );
	unregister_taxonomy( 'sseo_ai_room' );
	unregister_post_type( 'sseo_ai_book' );
	Simple_SEO_Fields::flush_types();

	// ------------------------------------------------------------------------------------------
	sseo_section( 'WP-CLI' );

	$sseo_vals = array();
	foreach ( array( 'fields', 'analyze', 'import', 'cleanup', 'post get', 'post update', 'term get', 'term update', 'indexnow status', 'indexnow submit', 'indexnow send' ) as $sseo_name ) {
		$sseo_vals[ $sseo_name ] = is_array( WP_CLI::get_runner()->find_command_to_run( array_merge( array( 'simple-seo' ), explode( ' ', $sseo_name ) ) ) );
	}
	sseo_check( 'the commands of wp simple-seo', ! in_array( false, $sseo_vals, true ), $sseo_vals );

	// The fields there are.
	$sseo_out  = sseo_cli( 'simple-seo fields --format=json' );
	$sseo_rows = array_column( (array) json_decode( $sseo_out->stdout, true ), null, 'field' );
	sseo_check(
		'fields: every field with where it is, its type, level, post types and label',
		0 === $sseo_out->return_code && array_keys( Simple_SEO_Fields::all() ) === array_keys( $sseo_rows )
			&& array( 'field' => 'nofollow', 'objects' => 'post, term', 'type' => 'checkbox', 'level' => 'advanced', 'post_types' => '', 'label' => Simple_SEO_Fields::get( 'nofollow' )['label'] ) === $sseo_rows['nofollow']
			&& 'post' === $sseo_rows['primary_category']['post_types'] && 'post' === $sseo_rows['keyphrase']['objects'],
		$sseo_out
	);
	$sseo_out = sseo_cli( 'simple-seo fields --object=term' );
	sseo_check( 'fields of terms, as a table', 0 === $sseo_out->return_code && str_starts_with( $sseo_out->stdout, "field\tobjects\ttype\tlevel\tpost_types\tlabel\ntitle\tpost, term\ttext\tbasic\t\tSEO title\n" ) && ! str_contains( $sseo_out->stdout, 'keyphrase' ), $sseo_out );

	// The fields of a post or term.
	$sseo['posts']['cli'] = wp_insert_post( array( 'post_title' => 'CLI post', 'post_content' => 'The words of the CLI post. They are few.', 'post_status' => 'publish' ) );
	$sseo_id              = (int) $sseo['posts']['cli'];
	delete_post_meta( $sseo_id, Simple_SEO_Scores::META );
	$sseo_val = Simple_SEO_Scores::get( get_post( $sseo_id ) );
	$sseo_out = sseo_cli( array( 'simple-seo', 'post', 'update', (string) $sseo_id ), array( 'title' => 'CLI {title}', 'nofollow' => true, 'og_image' => '0' ) );
	sseo_check(
		'post update: the fields given, a flag a ticked box; the scores of the post kept for its list',
		0 === $sseo_out->return_code && 'Success: Fields saved: title, nofollow, og_image.' === $sseo_out->stdout && 'CLI {title}' === Simple_SEO_Fields::post_value( $sseo_id, 'title' ) && '1' === get_post_meta( $sseo_id, '_simple_seo_nofollow', true )
			&& null === $sseo_val && null !== Simple_SEO_Scores::get( get_post( $sseo_id ) ),
		$sseo_out
	);
	$sseo_vals = array(
		json_decode( sseo_cli( 'simple-seo post get ' . $sseo_id . ' --format=json' )->stdout, true ),
		sseo_cli( 'simple-seo post get ' . $sseo_id . ' --field=title' )->stdout,
		sseo_cli( 'simple-seo post get ' . $sseo_id )->stdout,
	);
	sseo_check( 'post get: the fields as their types hold them; one field; a table', Simple_SEO_Fields::values( 'post', $sseo_id ) === $sseo_vals[0] && true === $sseo_vals[0]['nofollow'] && 'CLI {title}' === $sseo_vals[1] && str_starts_with( $sseo_vals[2], "Field\tValue\ntitle\tCLI {title}\n" ), $sseo_vals );
	$sseo_vals = array_map(
		static function ( string $command ): string {
			$out = sseo_cli( $command );

			return $out->return_code . ' ' . $out->stderr;
		},
		array(
			'simple-seo post update ' . $sseo_id . ' --title=Never --index=bogus',
			'simple-seo post update ' . $sseo_id,
			'simple-seo post update ' . PHP_INT_MAX . ' --title=x',
			'simple-seo post get ' . $sseo['posts']['hidden_type'],
			'simple-seo term update ' . $sseo_cat_id . ' --keyphrase=x',
			'simple-seo term get ' . PHP_INT_MAX,
		)
	);
	sseo_check(
		'errors: a value a field cannot hold (and nothing written), no field named, no such post or term, a field terms do not have',
		array(
			'1 Error: The SEO field index takes one of: index, noindex.',
			'1 Error: Name the fields to change, for example --title="…".',
			'1 Error: There is no such post with SEO fields.',
			'1 Error: There is no such post with SEO fields.',
			'1 Error: There is no SEO field keyphrase here.',
			'1 Error: There is no such term with SEO fields.',
		) === $sseo_vals && 'CLI {title}' === Simple_SEO_Fields::post_value( $sseo_id, 'title' ),
		$sseo_vals
	);
	$sseo_out = sseo_cli( array( 'simple-seo', 'post', 'update', (string) $sseo_id ), array( 'title' => '', 'nofollow' => '0' ) );
	sseo_check( 'post update: empty values clear', 0 === $sseo_out->return_code && ! metadata_exists( 'post', $sseo_id, '_simple_seo_title' ) && ! metadata_exists( 'post', $sseo_id, '_simple_seo_nofollow' ), $sseo_out );
	$sseo_kept = array( Simple_SEO_Fields::term_value( $sseo_cat_id, 'title' ), Simple_SEO_Fields::term_value( $sseo_cat_id, 'description' ) );
	$sseo_out  = sseo_cli( array( 'simple-seo', 'term', 'update', (string) $sseo_cat_id ), array( 'description' => 'Term via CLI', 'title' => '' ) );
	$sseo_val = json_decode( sseo_cli( 'simple-seo term get ' . $sseo_cat_id . ' --format=json' )->stdout, true );
	sseo_check( 'term update and get: the fields of terms, an empty value clears', 0 === $sseo_out->return_code && 'Success: Fields saved: description, title.' === $sseo_out->stdout && 'Term via CLI' === $sseo_val['description'] && '' === $sseo_val['title'] && ! metadata_exists( 'term', $sseo_cat_id, '_simple_seo_title' ) && array_keys( Simple_SEO_Fields::available( 'term' ) ) === array_keys( $sseo_val ), $sseo_val );
	Simple_SEO_Fields::write( 'term', $sseo_cat_id, array( 'title' => $sseo_kept[0], 'description' => $sseo_kept[1] ) );

	// The analysis.
	update_post_meta( $sseo_id, '_simple_seo_keyphrase', 'CLI post' );
	delete_post_meta( $sseo_id, Simple_SEO_Scores::META );
	$sseo_post   = get_post( $sseo_id );
	$sseo_result = Simple_SEO_Analysis::run( $sseo_post );
	$sseo_ctx    = Simple_SEO_Context::for_post( $sseo_post );
	$sseo_val    = json_decode( sseo_cli( 'simple-seo analyze ' . $sseo_id . ' --format=json' )->stdout, true );
	sseo_check(
		'analyze: the page as it shows, the scores and every check of both kinds; nothing kept',
		get_permalink( $sseo_post ) === $sseo_val['url'] && Simple_SEO_Titles::title( $sseo_ctx ) === $sseo_val['title'] && Simple_SEO_Titles::description( $sseo_ctx ) === $sseo_val['description'] && $sseo_result['words'] === $sseo_val['words']
			&& $sseo_result['score'] === $sseo_val['score'] && $sseo_result['rating'] === $sseo_val['rating'] && $sseo_result['readability']['score'] === $sseo_val['readability_score'] && $sseo_result['readability']['rating'] === $sseo_val['readability_rating']
			&& count( $sseo_result['checks'] ) + count( $sseo_result['readability']['checks'] ) === count( $sseo_val['checks'] ) && array( 'area' => 'seo' ) + $sseo_result['checks'][0] === $sseo_val['checks'][0]
			&& array( 'area' => 'readability' ) + end( $sseo_result['readability']['checks'] ) === end( $sseo_val['checks'] ) && null === Simple_SEO_Scores::get( $sseo_post ),
		$sseo_val
	);
	$sseo_vals = array( sseo_cli( 'simple-seo analyze ' . $sseo_id ), sseo_cli( 'simple-seo analyze ' . $sseo_id . ' --format=yaml' ), sseo_cli( 'simple-seo analyze ' . $sseo['posts']['hidden_type'] ) );
	sseo_check(
		'analyze as tables, as YAML; only posts with SEO fields',
		str_starts_with( $sseo_vals[0]->stdout, "Field\tValue\nurl\t" ) && str_contains( $sseo_vals[0]->stdout, "\nscore\t" . $sseo_result['score'] . "\n" ) && str_contains( $sseo_vals[0]->stdout, "\narea\tstatus\ttext\nseo\t" ) && str_contains( $sseo_vals[0]->stdout, "\nreadability\t" )
			&& str_contains( $sseo_vals[1]->stdout, 'readability_rating: ' ) && 1 === $sseo_vals[2]->return_code && 'Error: There is no such post with SEO fields.' === $sseo_vals[2]->stderr,
		$sseo_vals
	);

	// The import.
	$sseo_ref   = new ReflectionMethod( Simple_SEO_CLI::class, 'import_report' );
	$sseo_lines = $sseo_ref->invoke(
		null,
		'Simple_SEO_Rank_Math_Import',
		array(
			'settings'  => array(
				'separator' => 1,
				'templates' => 12,
			),
			'languages' => array( 'en', 'de' ),
			'post'      => array( 'seen' => 1200, 'changed' => 5, 'fields' => 9, 'kept' => 2, 'refused' => 1 ),
			'term'      => array( 'seen' => 4, 'changed' => 3, 'fields' => 6, 'kept' => 1, 'refused' => 0 ),
			'dropped'   => array( 'wc_price' => 3 ),
			'left'      => array(
				'bctitle'   => 2,
				'url_bases' => 1,
			),
		)
	);
	sseo_check(
		'the report of an import, as the tab gives it',
		array(
			'Settings taken: the separator, templates: 12.',
			'Also the home and 404 pages, the breadcrumb labels and the Schema names of the languages: en, de.',
			'Posts with SEO fields: 1,200, 5 of them changed. Fields filled: 9; kept as Simple SEO had them: 2; not taken, as Simple SEO cannot hold the value: 1.',
			'Terms with SEO fields: 4, 3 of them changed. Fields filled: 6; kept as Simple SEO had them: 1; not taken, as Simple SEO cannot hold the value: 0.',
			'Left out of the texts, as Simple SEO has no such variable: %wc_price% (3).',
			'Not taken, as Simple SEO has nothing for it yet:',
			'- titles for breadcrumbs (posts: 2)',
			'- addresses without the category base: with the plugin off, the addresses of categories get it back',
		) === $sseo_lines,
		$sseo_lines
	);
	$sseo_lines = $sseo_ref->invoke( null, 'Simple_SEO_Rank_Math_Import', array() );
	sseo_check( 'an empty report', 3 === count( $sseo_lines ) && 'Settings: nothing to take, Simple SEO has its own.' === $sseo_lines[0], $sseo_lines );

	foreach ( array( Simple_SEO_Rank_Math_Import::STATE, Simple_SEO_Rank_Math_Cleanup::OPTION, Simple_SEO_Aioseo_Import::STATE ) as $sseo_name ) {
		delete_option( $sseo_name );
	}
	$sseo['posts']['cli_rm'] = wp_insert_post( array( 'post_title' => 'Rank Math CLI', 'post_status' => 'publish' ) );
	$sseo_rm                 = (int) $sseo['posts']['cli_rm'];
	update_post_meta( $sseo_rm, 'rank_math_title', '%title% %wc_price% %sep% Shop' );
	update_post_meta( $sseo_rm, 'rank_math_breadcrumb_title', 'Crumb' );
	$sseo_out = sseo_cli( 'simple-seo import rank-math' );
	sseo_check(
		'import: run to the end, with the progress and the report; the field taken',
		0 === $sseo_out->return_code && str_starts_with( $sseo_out->stdout, "Posts: 1, terms: 0.\n" ) && str_contains( $sseo_out->stdout, "\nPosts with SEO fields: 1, 1 of them changed. Fields filled: 1;" ) && str_contains( $sseo_out->stdout, "\nLeft out of the texts, as Simple SEO has no such variable: %wc_price% (1).\n" )
			&& str_contains( $sseo_out->stdout, "\n- titles for breadcrumbs (posts: 1)\n" ) && str_ends_with( $sseo_out->stdout, "\nSuccess: The import from Rank Math is done." ) && '{title} {sep} Shop' === Simple_SEO_Fields::post_value( $sseo_rm, 'title' ) && 'done' === Simple_SEO_Import::state( 'rank_math' )['status'],
		$sseo_out
	);
	$sseo_broken = array(
		'status' => 'running',
		'phase'  => 'terms',
		'cursor' => 0,
		'report' => array( 'post' => array( 'seen' => 7 ) ),
	);
	update_option( Simple_SEO_Rank_Math_Import::STATE, $sseo_broken, false );
	$sseo_vals = array( sseo_cli( 'simple-seo import rank-math' ) );
	update_option( Simple_SEO_Rank_Math_Import::STATE, $sseo_broken, false );
	$sseo_vals[] = sseo_cli( 'simple-seo import rank-math --restart' );
	$sseo_vals[] = sseo_cli( 'simple-seo import aioseo' );
	sseo_check(
		'a run broken off goes on where it stopped, --restart starts again; a plugin without data is refused',
		0 === $sseo_vals[0]->return_code && str_starts_with( $sseo_vals[0]->stdout, "Posts: 7, terms: 0.\n" ) && 0 === $sseo_vals[1]->return_code && str_starts_with( $sseo_vals[1]->stdout, "Posts: 1, terms: 0.\n" )
			&& 1 === $sseo_vals[2]->return_code && 'Error: There is no data of All in One SEO on this site.' === $sseo_vals[2]->stderr && 'done' === Simple_SEO_Import::state( 'rank_math' )['status'],
		$sseo_vals
	);

	// Removing a plugin's data.
	$sseo_db = $GLOBALS['wpdb'];
	$sseo_db->query( "CREATE TABLE IF NOT EXISTS `{$sseo_db->prefix}rank_math_cli_test` ( id INT NOT NULL PRIMARY KEY )" );
	update_option( 'rank-math-options-general', array( 'x' => 1 ) );
	$sseo_rc_active = static fn( $plugins ): array => array_merge( (array) $plugins, array( 'seo-by-rank-math/rank-math.php' ) );
	add_filter( 'option_active_plugins', $sseo_rc_active );
	$sseo_vals = array( sseo_cli( 'simple-seo cleanup rank-math --yes' ) );
	remove_filter( 'option_active_plugins', $sseo_rc_active );
	update_option( Simple_SEO_Rank_Math_Import::STATE, array( 'status' => 'pending' ), false );
	$sseo_vals[] = sseo_cli( 'simple-seo cleanup rank-math --yes' );
	update_option( Simple_SEO_Rank_Math_Import::STATE, array( 'status' => 'done' ), false );
	$sseo_vals[] = sseo_cli( 'simple-seo cleanup rank-math --parts=tables,nope --yes' );
	$sseo_vals[] = sseo_cli( array( 'simple-seo', 'cleanup', 'rank-math' ), array( 'parts' => '', 'yes' => true ) );
	$sseo_vals   = array_map( static fn( object $out ): string => $out->return_code . ' ' . $out->stderr, $sseo_vals );
	sseo_check(
		'cleanup refused: Rank Math active, its import not done, an unknown part, no part; nothing removed',
		array(
			'1 Error: Rank Math is active, so its data is in use. Deactivate it first.',
			'1 Error: Run the import first: removing comes after it.',
			'1 Error: No such part: nope. The parts: tables, internals, settings, usermeta, termmeta, postmeta.',
			'1 Error: No such part: "". The parts: tables, internals, settings, usermeta, termmeta, postmeta.',
		) === $sseo_vals && array() === Simple_SEO_Rank_Math_Cleanup::state() && (bool) $sseo_db->get_var( $sseo_db->prepare( 'SHOW TABLES LIKE %s', $sseo_db->prefix . 'rank_math_cli_test' ) ),
		$sseo_vals
	);
	// Rank Math switched on while its data goes: the command stops with an error, it does not spin.
	$sseo_rc_later = static fn( $plugins ): array => 'running' === ( Simple_SEO_Rank_Math_Cleanup::state()['status'] ?? '' ) ? array_merge( (array) $plugins, array( 'seo-by-rank-math/rank-math.php' ) ) : (array) $plugins;
	add_filter( 'option_active_plugins', $sseo_rc_later );
	$sseo_vals = array( sseo_cli( 'simple-seo cleanup rank-math --parts=tables --yes' ) );
	remove_filter( 'option_active_plugins', $sseo_rc_later );
	$sseo_vals[] = (bool) $sseo_db->get_var( $sseo_db->prepare( 'SHOW TABLES LIKE %s', $sseo_db->prefix . 'rank_math_cli_test' ) );
	$sseo_vals[] = sseo_cli( 'simple-seo cleanup rank-math' );
	sseo_check(
		'stopped short of the end: an error; the next run goes on with it',
		1 === $sseo_vals[0]->return_code && 'Error: It stopped before the end: run the command again to go on.' === $sseo_vals[0]->stderr && true === $sseo_vals[1]
			&& 0 === $sseo_vals[2]->return_code && 'Success: Removed: tables: 1.' === $sseo_vals[2]->stdout && 'done' === Simple_SEO_Rank_Math_Cleanup::state()['status'],
		$sseo_vals
	);
	$sseo_db->query( "CREATE TABLE IF NOT EXISTS `{$sseo_db->prefix}rank_math_cli_test` ( id INT NOT NULL PRIMARY KEY )" );
	$sseo_cli_theme = get_theme_root() . '/sseo-cli-theme';
	wp_mkdir_p( $sseo_cli_theme );
	file_put_contents( $sseo_cli_theme . '/functions.php', "<?php get_post_meta( 1, 'rank_math_title', true );" );
	$sseo_cli_dir = static fn(): string => $sseo_cli_theme;
	add_filter( 'stylesheet_directory', $sseo_cli_dir );
	$sseo_vals = array( sseo_cli( 'simple-seo cleanup rank-math --yes' ) );
	$sseo_vals[] = (int) $sseo_db->get_var( $sseo_db->prepare( "SELECT COUNT(*) FROM {$sseo_db->postmeta} WHERE post_id = %d AND meta_key LIKE 'rank\\_math\\_%%'", $sseo_rm ) );
	$sseo_vals[] = sseo_cli( 'simple-seo cleanup rank-math --parts=postmeta --yes' );
	remove_filter( 'stylesheet_directory', $sseo_cli_dir );
	unlink( $sseo_cli_theme . '/functions.php' );
	rmdir( $sseo_cli_theme );
	sseo_check(
		'cleanup: what goes as a table, the part the theme reads kept; named, it goes with a warning',
		0 === $sseo_vals[0]->return_code && str_contains( $sseo_vals[0]->stdout, "Kept, as the active theme reads it: postmeta (sseo-cli-theme/functions.php).\npart\trows\tsize\tholds\ntables\t1\t" ) && str_ends_with( $sseo_vals[0]->stdout, "\nSuccess: Removed: tables: 1; rows of settings: 1." )
			&& 2 === $sseo_vals[1] && 0 === $sseo_vals[2]->return_code && 'Warning: The active theme reads postmeta (sseo-cli-theme/functions.php): removed, it is gone for the theme too.' === $sseo_vals[2]->stderr && str_ends_with( $sseo_vals[2]->stdout, "\nSuccess: Removed: rows of post meta: 2." )
			&& '' === get_post_meta( $sseo_rm, 'rank_math_title', true ) && false === get_option( 'rank-math-options-general' ) && '{title} {sep} Shop' === Simple_SEO_Fields::post_value( $sseo_rm, 'title' ),
		$sseo_vals
	);
	update_post_meta( $sseo_rm, 'rank_math_description', 'x' );
	$sseo_db->query( "CREATE TABLE IF NOT EXISTS `{$sseo_db->prefix}rank_math_cli_test` ( id INT NOT NULL PRIMARY KEY )" );
	Simple_SEO_Rank_Math_Cleanup::start( array( 'postmeta' ) );
	$sseo_vals = array( sseo_cli( 'simple-seo cleanup rank-math --yes' ), (bool) $sseo_db->get_var( $sseo_db->prepare( 'SHOW TABLES LIKE %s', $sseo_db->prefix . 'rank_math_cli_test' ) ) );
	$sseo_db->query( "DROP TABLE IF EXISTS `{$sseo_db->prefix}rank_math_cli_test`" );
	$sseo_vals[] = sseo_cli( 'simple-seo cleanup rank-math --yes' );
	sseo_check(
		'a removal under way goes on with its own parts, not all that is left; then nothing is left',
		0 === $sseo_vals[0]->return_code && 'Success: Removed: rows of post meta: 1.' === $sseo_vals[0]->stdout && '' === get_post_meta( $sseo_rm, 'rank_math_description', true ) && true === $sseo_vals[1]
			&& 0 === $sseo_vals[2]->return_code && 'Success: There is no data of Rank Math on this site.' === $sseo_vals[2]->stdout,
		$sseo_vals
	);
	foreach ( array_merge( $sseo_yi_rows, array( Simple_SEO_Rank_Math_Import::STATE, Simple_SEO_Rank_Math_Cleanup::OPTION ) ) as $sseo_name ) {
		delete_option( $sseo_name );
	}
	Simple_SEO_Settings::install();
	Simple_SEO_Settings::flush();

	// ------------------------------------------------------------------------------------------
	sseo_section( 'Abilities' );

	// Earlier sections leave the access row empty: the rights by default for this one.
	$sseo_access = get_option( Simple_SEO_Access::OPTION );
	update_option( Simple_SEO_Access::OPTION, Simple_SEO_Access::defaults() );
	$sseo_ab    = static fn( string $name, $input = null ) => wp_get_ability( $name )->execute( $input );
	$sseo_code  = static fn( $value ): string => is_wp_error( $value ) ? $value->get_error_code() : 'no error';
	$sseo_names = array( 'simple-seo/get-fields', 'simple-seo/update-fields', 'simple-seo/find', 'simple-seo/analyze', 'simple-seo/search-console', 'simple-seo/settings', 'simple-seo/indexnow-status', 'simple-seo/indexnow-submit' );
	$sseo_found = array_values( array_filter( array_map( static fn( WP_Ability $ability ): string => $ability->get_name(), wp_get_abilities() ), static fn( string $name ): bool => str_starts_with( $name, 'simple-seo/' ) ) );
	$sseo_notes = array();
	foreach ( $sseo_names as $sseo_name ) {
		$sseo_a     = wp_get_ability( $sseo_name );
		$sseo_ann   = (array) ( $sseo_a ? $sseo_a->get_meta()['annotations'] : array() );
		$sseo_props = $sseo_a ? (array) ( $sseo_a->get_input_schema()['properties'] ?? array() ) : array();
		$sseo_notes[ $sseo_name ] = $sseo_a ? array(
			$sseo_a->get_category(),
			true === ( $sseo_a->get_meta()['mcp']['public'] ?? null ),
			( ! empty( $sseo_ann['readonly'] ) ? 'r' : '-' ) . ( ! empty( $sseo_ann['destructive'] ) ? 'd' : '-' ) . ( ! empty( $sseo_ann['idempotent'] ) ? 'i' : '-' ),
			'' !== $sseo_a->get_label() && mb_strlen( $sseo_a->get_description() ) <= 2048,
			array() === array_filter( $sseo_props, static fn( array $prop ): bool => '' === (string) ( $prop['description'] ?? '' ) ),
			false === ( $sseo_a->get_input_schema()['additionalProperties'] ?? null ),
		) : 'missing';
	}
	sseo_check(
		'eight abilities in the category Simple SEO, each for MCP, with a label, a description an MCP server keeps whole, every argument described and no other taken; which read, overwrite, repeat',
		$sseo_names === $sseo_found && wp_get_ability_category( Simple_SEO_Abilities::CATEGORY ) instanceof WP_Ability_Category && 'Simple SEO' === wp_get_ability_category( Simple_SEO_Abilities::CATEGORY )->get_label()
			&& array(
				'simple-seo/get-fields'      => array( 'simple-seo', true, 'r-i', true, true, true ),
