	$sseo_au_html = static fn( string $head, string $body ): string => '<!doctype html><html lang="uk"><head><meta charset="utf-8">' . $head . '</head><body>' . $body . '</body></html>';
	$sseo_vals    = Simple_SEO_Audit::parse(
