	$sseo_wc_set( array( 'mode' => 'always' ) );
	wp_set_current_user( 0 );

	$sseo_vals = array( Simple_SEO_Schema::builtin_page_type( 'product' ), Simple_SEO_Schema::builtin_page_type( 'post' ), Simple_SEO_Schema::builtin_page_type( 'page' ), Simple_SEO_Schema::default_page_type( 'product' ), Simple_SEO_Schema::default_page_type( 'page' ) );
	sseo_check( 'products are item pages by default, the rest web pages', array( 'ItemPage', 'WebPage', 'WebPage', 'ItemPage', 'WebPage' ) === $sseo_vals, $sseo_vals );

	// WooCommerce's JSON-LD where Simple SEO's graph is printed: none of what the graph says.
	$sseo_wc_types = array( 'product', '', 'website', 'onlinestore', 'review', 'breadcrumblist', 'order' );
	$sseo_wc_show( array( 'p' => $sseo_p['author_post'] ) );
	$sseo_vals = array(
		Simple_SEO_WooCommerce::woocommerce_types( $sseo_wc_types ),
		Simple_SEO_WooCommerce::woocommerce_types( array( 'product', 'review' ) ),
		Simple_SEO_WooCommerce::woocommerce_types( 'x' ),
	);
	$sseo_wc_set( array( 'mode' => 'always', 'breadcrumbs' => false ) );
	$sseo_wc_show( array( 'p' => $sseo_p['author_post'] ) );
	$sseo_vals[] = Simple_SEO_WooCommerce::woocommerce_types( $sseo_wc_types );
	$sseo_wc_set( array( 'mode' => 'off' ) );
	$sseo_vals[] = Simple_SEO_WooCommerce::woocommerce_types( $sseo_wc_types );
	$sseo_wc_set( array( 'mode' => 'always' ) );
	sseo_check(
		'WooCommerce\'s JSON-LD with the graph of Simple SEO: only what the graph does not say, the trail when it has none; one that is none rather than an empty list; all without the graph',
		array( array( 'order' ), array( 'none' ), 'x', array( 'breadcrumblist', 'order' ), $sseo_wc_types ) === $sseo_vals && has_filter( 'woocommerce_structured_data_type_for_page', array( Simple_SEO_WooCommerce::class, 'woocommerce_types' ) ),
		$sseo_vals
	);

	// The page of a post type's archive (simple_seo_archive_page): its fields, title, excerpt and image.
	$sseo_wc_arch = (int) wp_insert_post( array( 'post_title' => 'Aitest library', 'post_type' => 'page', 'post_status' => 'publish', 'post_excerpt' => 'All the <b>books</b>.' ) );
	$sseo['posts'][] = $sseo_wc_arch;
	update_post_meta( $sseo_wc_arch, Simple_SEO_Fields::meta_key( 'description' ), 'The books of the library.' );
	$sseo_wc_cover = (int) wp_insert_attachment( array( 'post_title' => 'Libcover', 'post_mime_type' => 'image/jpeg', 'post_status' => 'inherit' ), 'lib-cover.jpg' );
	$sseo['posts'][] = $sseo_wc_cover;
	set_post_thumbnail( $sseo_wc_arch, $sseo_wc_cover );
	$sseo_wc_book = (int) wp_insert_post( array( 'post_title' => 'Aitest novel', 'post_type' => 'sseo_book', 'post_status' => 'publish' ) );
	$sseo['posts'][] = $sseo_wc_book;
	$sseo_ctx  = Simple_SEO_Context::for_post_type_archive( 'sseo_book' );
	$sseo_vals = array( $sseo_ctx->object_id, $sseo_ctx->has_fields(), Simple_SEO_Context::archive_page( 'sseo_book' ), Simple_SEO_Variables::object_title( $sseo_ctx ) );
	$sseo_wc_page = static fn( $id, string $post_type ) => 'sseo_book' === $post_type ? $GLOBALS['sseo_wc_arch_id'] : $id;
	$GLOBALS['sseo_wc_arch_id'] = $sseo_wc_arch;
	add_filter( 'simple_seo_archive_page', $sseo_wc_page, 10, 2 );
	$sseo_ctx    = Simple_SEO_Context::for_post_type_archive( 'sseo_book' );
	$sseo_vals[] = array( $sseo_ctx->object_id, $sseo_ctx->has_fields(), $sseo_ctx->field( 'description' ), Simple_SEO_Variables::object_title( $sseo_ctx ), Simple_SEO_Variables::excerpt( $sseo_ctx ), Simple_SEO_Social::image_id( $sseo_ctx ) );
	$sseo_vals[] = Simple_SEO_Titles::description( $sseo_ctx );
	$sseo_vals[] = array_column( Simple_SEO_Breadcrumbs::items( $sseo_ctx ), 'label' );
	$sseo_vals[] = array_column( Simple_SEO_Breadcrumbs::items( Simple_SEO_Context::for_post( get_post( $sseo_wc_book ) ) ), 'label' );
	$sseo_vals[] = Simple_SEO_Context::from_query( sseo_query( array( 'post_type' => 'sseo_book' ) ) )->object_id;
	wp_update_post( array( 'ID' => $sseo_wc_arch, 'post_excerpt' => '' ) );
	$sseo_wc_desc = get_post_type_object( 'sseo_book' )->description;
	get_post_type_object( 'sseo_book' )->description = 'The books, all of them.';
	$sseo_vals[] = Simple_SEO_Variables::excerpt( Simple_SEO_Context::for_post_type_archive( 'sseo_book' ) );
	get_post_type_object( 'sseo_book' )->description = $sseo_wc_desc;
	wp_update_post( array( 'ID' => $sseo_wc_arch, 'post_status' => 'draft' ) );
	$sseo_vals[] = Simple_SEO_Context::for_post_type_archive( 'sseo_book' )->object_id;
	$GLOBALS['sseo_wc_arch_id'] = $sseo_wc_book;
	$sseo_vals[] = Simple_SEO_Context::archive_page( 'sseo_book' );
	remove_filter( 'simple_seo_archive_page', $sseo_wc_page, 10 );
	unset( $GLOBALS['sseo_wc_arch_id'] );
	sseo_check(
		'the page of an archive: none by default; its SEO fields, title, excerpt (else the type\'s description) and image are the archive\'s, and its title in the trails; published, and a page only',
		array( 0, false, null, 'Books' ) === array_slice( $sseo_vals, 0, 4 )
			&& array( $sseo_wc_arch, true, 'The books of the library.', 'Aitest library', 'All the <b>books</b>.', $sseo_wc_cover ) === $sseo_vals[4]
			&& 'The books of the library.' === $sseo_vals[5] && array( 'Home', 'Aitest library' ) === $sseo_vals[6] && array( 'Home', 'Aitest library', 'Aitest novel' ) === $sseo_vals[7] && $sseo_wc_arch === $sseo_vals[8]
			&& 'The books, all of them.' === $sseo_vals[9] && 0 === $sseo_vals[10] && null === $sseo_vals[11],
		$sseo_vals
	);
	$sseo_wc_tax = static fn( $taxonomy, string $post_type ) => 'post' === $post_type ? 'sseo_nope' : $taxonomy;
	add_filter( 'simple_seo_breadcrumb_taxonomy', $sseo_wc_tax, 10, 2 );
	$sseo_vals = array( Simple_SEO_Breadcrumbs::default_taxonomy( 'post' ) );
	remove_filter( 'simple_seo_breadcrumb_taxonomy', $sseo_wc_tax, 10 );
	sseo_check( 'the taxonomy of a trail by the filter, one the post type has only', array( 'category' ) === $sseo_vals, $sseo_vals );

	if ( ! Simple_SEO_WooCommerce::active() ) {
		$sseo_ctx  = Simple_SEO_Context::current();
		$sseo_vals = array(
			Simple_SEO_WooCommerce::schema_pieces( array( 'webpage' => array( '@id' => 'x' ) ), $sseo_ctx ),
			Simple_SEO_WooCommerce::head_tags( array( 'og:type' => array( 'tag' => 'meta', 'attributes' => array( 'property' => 'og:type', 'content' => 'article' ) ) ), $sseo_ctx ),
			Simple_SEO_WooCommerce::product( $sseo_ctx ),
			Simple_SEO_WooCommerce::return_policy(),
		);
		sseo_check(
			'without WooCommerce: no product, no policy, the graph and the tags as they are',
			array( array( 'webpage' => array( '@id' => 'x' ) ), array( 'og:type' => array( 'tag' => 'meta', 'attributes' => array( 'property' => 'og:type', 'content' => 'article' ) ) ), null, '' ) === $sseo_vals
				&& array() === Simple_SEO_WooCommerce::pages() && array( 5 ) === Simple_SEO_WooCommerce::sitemap_exclude( array( 5 ), 'post', 'page' ) && 7 === Simple_SEO_WooCommerce::archive_page( 7, 'product' ) && false === Simple_SEO_WooCommerce::noindex( false, Simple_SEO_Context::current() ),
			$sseo_vals
		);
	} else {
		// The pieces of a page's graph as the filters make them.
		$sseo_wc_pieces = static fn( Simple_SEO_Context $context ): array => (array) apply_filters( 'simple_seo_schema_pieces', Simple_SEO_Schema::pieces( $context ), $context );

		// Products, a brand, an image, a review.
		$sseo_wc_product = static function ( array $set ) use ( &$sseo ): int {
			$product = new WC_Product_Simple();
			$product->set_name( $set['name'] );
			$product->set_status( 'publish' );
			foreach ( array( 'regular_price', 'sale_price', 'sku', 'global_unique_id', 'short_description', 'stock_status', 'image_id' ) as $key ) {
				if ( isset( $set[ $key ] ) ) {
					$product->{'set_' . $key}( $set[ $key ] );
				}
			}
			$id              = (int) $product->save();
			$sseo['posts'][] = $id;

			return $id;
		};
		$sseo_wc_image = (int) wp_insert_attachment( array( 'post_title' => 'Wooimage', 'post_mime_type' => 'image/jpeg', 'post_status' => 'inherit' ), 'woo-oak-table.jpg' );
		$sseo['posts'][] = $sseo_wc_image;
		update_post_meta( $sseo_wc_image, '_wp_attachment_metadata', array( 'width' => 800, 'height' => 600, 'file' => 'woo-oak-table.jpg' ) );
		$sseo_wc_table = $sseo_wc_product(
			array(
				'name'              => 'Wootest oak table',
				'regular_price'     => '100',
				'sale_price'        => '80',
				'sku'               => 'OAK-1',
				'global_unique_id'  => '4006381333931',
				'short_description' => 'A solid <b>oak</b> table.',
				'image_id'          => $sseo_wc_image,
			)
		);
		$sseo_wc_brands = array();
		foreach ( array( 'Woobrand one', 'Woobrand two' ) as $sseo_name ) {
			$sseo_term        = wp_insert_term( $sseo_name, Simple_SEO_WooCommerce::BRANDS );
			$sseo_wc_brands[] = (int) $sseo_term['term_id'];
			$sseo['terms'][]  = array( (int) $sseo_term['term_id'], Simple_SEO_WooCommerce::BRANDS );
		}
		wp_set_object_terms( $sseo_wc_table, $sseo_wc_brands, Simple_SEO_WooCommerce::BRANDS );
		update_post_meta( $sseo_wc_table, Simple_SEO_Fields::meta_key( Simple_SEO_Primary_Term::field( Simple_SEO_WooCommerce::BRANDS ) ), (string) $sseo_wc_brands[1] );
		$sseo_val = (int) wp_insert_comment( array( 'comment_post_ID' => $sseo_wc_table, 'comment_content' => 'Great table', 'comment_type' => 'review', 'comment_approved' => 1, 'comment_author' => 'Ann' ) );
		update_comment_meta( $sseo_val, 'rating', 5 );
		WC_Comments::clear_transients( $sseo_wc_table );
		$sseo_wc_bare = $sseo_wc_product( array( 'name' => 'Wootest no price' ) );

		$sseo_ctx   = $sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) );
		$sseo_graph = Simple_SEO_Schema::graph( $sseo_ctx );
		$sseo_url   = (string) get_permalink( $sseo_wc_table );
		$sseo_node  = array_values( array_filter( $sseo_graph, static fn( array $node ): bool => 'Product' === ( $node['@type'] ?? '' ) ) )[0] ?? array();
		$sseo_page  = array_values( array_filter( $sseo_graph, static fn( array $node ): bool => $sseo_url === ( $node['@id'] ?? '' ) ) )[0] ?? array();
		sseo_check(
			'a product in the graph: WooCommerce\'s own, the main entity of its item page, with the image of the page, the site as the seller and the primary brand',
			$sseo_url . '#product' === ( $sseo_node['@id'] ?? null ) && array( '@id' => $sseo_url ) === ( $sseo_node['mainEntityOfPage'] ?? null ) && array( '@id' => $sseo_url . '#primaryimage' ) === ( $sseo_node['image'] ?? null )
				&& array( '@type' => 'Brand', 'name' => 'Woobrand two' ) === ( $sseo_node['brand'] ?? null ) && 'ItemPage' === ( $sseo_page['@type'] ?? null )
				&& 'Wootest oak table' === $sseo_node['name'] && 'OAK-1' === $sseo_node['sku'] && '4006381333931' === $sseo_node['gtin'] && 'A solid oak table.' === $sseo_node['description']
				&& array( '@id' => home_url( '/' ) . '#organization' ) === ( $sseo_node['offers'][0]['seller'] ?? null ) && '80.00' === ( $sseo_node['offers'][0]['price'] ?? null ) && 'https://schema.org/InStock' === $sseo_node['offers'][0]['availability']
				&& '5.00' === (string) ( $sseo_node['aggregateRating']['ratingValue'] ?? '' ) && 'Ann' === ( $sseo_node['review'][0]['author']['name'] ?? null ),
			$sseo_graph
		);
		// A brand with its picture: its logo.
		update_term_meta( $sseo_wc_brands[1], 'thumbnail_id', $sseo_wc_image );
		$sseo_vals = array( $sseo_wc_pieces( $sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) ) )['product']['brand'] ?? null );
		delete_term_meta( $sseo_wc_brands[1], 'thumbnail_id' );
		sseo_check( 'a brand with a picture has its logo', array( '@type' => 'Brand', 'name' => 'Woobrand two', 'logo' => wp_get_attachment_image_url( $sseo_wc_image, 'full' ) ) === $sseo_vals[0] && '' !== (string) wp_get_attachment_image_url( $sseo_wc_image, 'full' ), $sseo_vals );

		// The type of page of products in the settings.
		wp_set_current_user( $sseo_u['administrator'] );
		$sseo_vals = array(
			Simple_SEO_Schema::sanitize( array( 'page_types' => array( 'product' => 'ItemPage', 'page' => 'WebPage' ) ) )['page_types'],
			Simple_SEO_Schema::sanitize( array( 'page_types' => array( 'product' => 'WebPage' ) ) )['page_types'],
			(bool) preg_match( '/name="simple_seo_schema\[page_types\]\[product\]">.*?<option value="ItemPage"\s+selected/s', sseo_capture( array( Simple_SEO_Schema::class, 'render_tab' ) ) ),
		);
		wp_set_current_user( 0 );
		sseo_check( 'the type of page of products: item page by default on the tab, kept only when it differs', array( array(), array( 'product' => 'WebPage' ), true ) === $sseo_vals, $sseo_vals );

		$sseo_vals = array();
		$sseo_vals['no price'] = array_keys( $sseo_wc_pieces( $sseo_wc_show( array( 'p' => $sseo_wc_bare, 'post_type' => 'product' ) ) ) );
		wp_update_post( array( 'ID' => $sseo_wc_bare, 'post_password' => 'secret' ) );
		update_post_meta( $sseo_wc_bare, '_regular_price', '10' );
		update_post_meta( $sseo_wc_bare, '_price', '10' );
		wc_delete_product_transients( $sseo_wc_bare );
		$sseo_vals['password'] = array_keys( $sseo_wc_pieces( $sseo_wc_show( array( 'p' => $sseo_wc_bare, 'post_type' => 'product' ) ) ) );
		$sseo_vals['a post']   = isset( $sseo_wc_pieces( $sseo_wc_show( array( 'p' => $sseo_p['author_post'] ) ) )['product'] );
		wp_update_post( array( 'ID' => $sseo_wc_bare, 'post_password' => '' ) );
		wp_set_object_terms( $sseo_wc_table, array(), Simple_SEO_WooCommerce::BRANDS );
		$sseo_vals['no brand'] = $sseo_wc_pieces( $sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) ) )['product']['brand'] ?? null;
		wp_set_object_terms( $sseo_wc_table, $sseo_wc_brands, Simple_SEO_WooCommerce::BRANDS );
		$sseo_wc_set( array( 'mode' => 'always', 'represents' => 'person', 'person' => $sseo_u['administrator'] ) );
		$sseo_vals['person']    = $sseo_wc_pieces( $sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) ) )['product']['offers'][0]['seller'] ?? null;
		$sseo_vals['person id'] = Simple_SEO_Schema::publisher()['@id'] ?? null;
		$sseo_wc_set( array( 'mode' => 'always' ) );
		sseo_check(
			'no product node: WooCommerce makes none without a price or a rating, none behind a password, none on a post; no brand, none said; a person as the seller',
			! in_array( 'product', $sseo_vals['no price'], true ) && in_array( 'webpage', $sseo_vals['no price'], true ) && ! in_array( 'product', $sseo_vals['password'], true ) && false === $sseo_vals['a post'] && null === $sseo_vals['no brand']
				&& is_string( $sseo_vals['person id'] ) && ! str_ends_with( $sseo_vals['person id'], '#organization' ) && array( '@id' => $sseo_vals['person id'] ) === $sseo_vals['person'],
			$sseo_vals
		);

		// The return policy.
		$sseo_wc_refund = (int) wc_get_page_id( 'refund_returns' );
		$sseo_vals      = array( Simple_SEO_WooCommerce::return_policy(), isset( $sseo_wc_pieces( $sseo_wc_show( array() ) )['organization']['hasMerchantReturnPolicy'] ) );
		wp_update_post( array( 'ID' => $sseo_wc_refund, 'post_status' => 'publish' ) );
		$sseo_wc_link = (string) get_permalink( $sseo_wc_refund );
		$sseo_vals[]  = Simple_SEO_WooCommerce::return_policy();
		$sseo_vals[] = $sseo_wc_pieces( $sseo_wc_show( array() ) )['organization']['hasMerchantReturnPolicy'] ?? null;
		wp_update_post( array( 'ID' => $sseo_wc_refund, 'post_password' => 'secret' ) );
		$sseo_vals[] = Simple_SEO_WooCommerce::return_policy();
		wp_update_post( array( 'ID' => $sseo_wc_refund, 'post_password' => '', 'post_status' => 'draft' ) );
		sseo_check(
			'the return policy of the shop on the organization, when its page is published and open',
			array( '', false, $sseo_wc_link, array( '@type' => 'MerchantReturnPolicy', 'merchantReturnLink' => $sseo_wc_link ), '' ) === $sseo_vals && str_contains( $sseo_wc_link, 'refund_returns' ),
			$sseo_vals
		);

		// Open Graph of a product.
		$sseo_og = static function ( Simple_SEO_Context $context ): array {
			$tags = array();
			foreach ( Simple_SEO_Head::tags( $context ) as $key => $tag ) {
				if ( preg_match( '/^(og:type|product:|article:)/', $key ) ) {
					$tags[ $key ] = $tag['attributes']['content'];
				}
			}

			return $tags;
		};
		$sseo_vals = array( $sseo_og( $sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) ) ) );
		foreach ( array( 'outofstock', 'onbackorder' ) as $sseo_name ) {
			$sseo_product = wc_get_product( $sseo_wc_table );
			$sseo_product->set_stock_status( $sseo_name );
			$sseo_product->save();
			$sseo_vals[] = Simple_SEO_WooCommerce::availability( wc_get_product( $sseo_wc_table ) );
		}
		$sseo_vals[] = $sseo_og( $sseo_wc_show( array( 'p' => $sseo_wc_bare, 'post_type' => 'product' ) ) );
		update_post_meta( $sseo_wc_bare, '_regular_price', '' );
		update_post_meta( $sseo_wc_bare, '_price', '' );
		wc_delete_product_transients( $sseo_wc_bare );
		$sseo_vals[] = $sseo_og( $sseo_wc_show( array( 'p' => $sseo_wc_bare, 'post_type' => 'product' ) ) );
		$sseo_vals[] = $sseo_og( $sseo_wc_show( array( 'p' => $sseo_p['author_post'] ) ) );
		sseo_check(
			'Open Graph of a product: of the type product, its price as shown, the currency, availability, code and brand, no dates of an article',
			array( 'og:type' => 'product', 'product:price:amount' => '80.00', 'product:price:currency' => get_woocommerce_currency(), 'product:availability' => 'in stock', 'product:retailer_item_id' => 'OAK-1', 'product:brand' => 'Woobrand two' ) === $sseo_vals[0]
				&& 'out of stock' === $sseo_vals[1] && 'available for order' === $sseo_vals[2]
				&& array( 'og:type' => 'product', 'product:price:amount' => '10.00', 'product:price:currency' => get_woocommerce_currency(), 'product:availability' => 'in stock' ) === $sseo_vals[3]
				&& array( 'og:type' => 'product', 'product:availability' => 'in stock' ) === $sseo_vals[4]
				&& 'article' === ( $sseo_vals[5]['og:type'] ?? null ) && isset( $sseo_vals[5]['article:published_time'] ),
			$sseo_vals
		);

		// WooCommerce prints none of its own on the page of a product.
		$sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) );
		$GLOBALS['post'] = get_post( $sseo_wc_table );
		WC()->structured_data->generate_product_data( wc_get_product( $sseo_wc_table ) );
		$sseo_vals = array( sseo_capture( array( WC()->structured_data, 'output_structured_data' ) ) );
		$sseo_wc_set( array( 'mode' => 'off' ) );
		$sseo_vals[] = sseo_capture( array( WC()->structured_data, 'output_structured_data' ) );
		$sseo_wc_set( array( 'mode' => 'always' ) );
		unset( $GLOBALS['post'] );
		sseo_check( 'WooCommerce prints no JSON-LD of its own where the graph has the product; with the graph off, its own', '' === $sseo_vals[0] && str_contains( $sseo_vals[1], '"@type":"Product"' ), $sseo_vals );

		// The shop, the trails, the cart and the sitemaps.
		$sseo_wc_shop = (int) wc_get_page_id( 'shop' );
		$sseo_wc_cats = array();
		foreach ( array( 'Woocat tables', 'Woocat oak' ) as $sseo_name ) {
			$sseo_term       = wp_insert_term( $sseo_name, 'product_cat', $sseo_wc_cats ? array( 'parent' => $sseo_wc_cats[0] ) : array() );
			$sseo_wc_cats[]  = (int) $sseo_term['term_id'];
			$sseo['terms'][] = array( (int) $sseo_term['term_id'], 'product_cat' );
		}
		wp_set_object_terms( $sseo_wc_table, array( $sseo_wc_cats[1] ), 'product_cat' );
		update_post_meta( $sseo_wc_shop, Simple_SEO_Fields::meta_key( 'description' ), 'Our shop of oak.' );
		$sseo_ctx  = $sseo_wc_show( array( 'post_type' => 'product' ) );
		$sseo_vals = array( $sseo_ctx->kind, $sseo_ctx->object_id, Simple_SEO_Titles::title( $sseo_ctx ), Simple_SEO_Titles::description( $sseo_ctx ), array_column( Simple_SEO_Breadcrumbs::items( $sseo_ctx ), 'label' ) );
		$sseo_vals[] = array_column( Simple_SEO_Breadcrumbs::items( $sseo_wc_show( array( 'p' => $sseo_wc_table, 'post_type' => 'product' ) ) ), 'label' );
		$sseo_vals[] = array_column( Simple_SEO_Breadcrumbs::items( $sseo_wc_show( array( 'product_cat' => get_term( $sseo_wc_cats[1] )->slug ) ) ), 'label' );
		$sseo_vals[] = Simple_SEO_Breadcrumbs::default_taxonomy( 'product' );
		$sseo_vals[] = Simple_SEO_WooCommerce::breadcrumb_taxonomy( 'category', 'post' );
		delete_post_meta( $sseo_wc_shop, Simple_SEO_Fields::meta_key( 'description' ) );
		$sseo_shop = get_the_title( $sseo_wc_shop );
		sseo_check(
			'the shop: the archive of products with the shop page\'s fields and title; the trails of products and their categories through the shop and the categories',
			array( Simple_SEO_Context::POST_TYPE_ARCHIVE, $sseo_wc_shop, $sseo_shop . ' ' . $sseo_sep . ' ' . $sseo_site, 'Our shop of oak.', array( 'Home', $sseo_shop ) ) === array_slice( $sseo_vals, 0, 5 )
				&& array( 'Home', $sseo_shop, 'Woocat tables', 'Woocat oak', 'Wootest oak table' ) === $sseo_vals[5] && array( 'Home', $sseo_shop, 'Woocat tables', 'Woocat oak' ) === $sseo_vals[6] && 'product_cat' === $sseo_vals[7] && 'category' === $sseo_vals[8],
			$sseo_vals
		);
		$sseo_vals = array();
		foreach ( Simple_SEO_WooCommerce::PAGES as $sseo_name ) {
			$sseo_ctx                = $sseo_wc_show( array( 'page_id' => (int) wc_get_page_id( $sseo_name ) ) );
			$sseo_vals[ $sseo_name ] = array( Simple_SEO_Indexing::is_noindex( $sseo_ctx ), Simple_SEO_Indexing::canonical( $sseo_ctx ) );
		}
		$sseo_vals['a page'] = Simple_SEO_Indexing::is_noindex( $sseo_wc_show( array( 'page_id' => $sseo_wc_arch ) ) );
		$sseo_wc_account = get_option( 'woocommerce_myaccount_page_id' );
		update_option( 'woocommerce_myaccount_page_id', '' );
		$sseo_vals['no account'] = Simple_SEO_WooCommerce::pages();
		update_option( 'woocommerce_myaccount_page_id', $sseo_wc_account );
		$sseo_vals['no account'] = array( (int) wc_get_page_id( 'cart' ), (int) wc_get_page_id( 'checkout' ) ) === $sseo_vals['no account'];
		sseo_check(
			'the cart, the checkout and the account: hidden from search engines, no canonical; other pages as they were; a page WooCommerce has not, none',
			array( 'cart' => array( true, '' ), 'checkout' => array( true, '' ), 'myaccount' => array( true, '' ), 'a page' => false, 'no account' => true ) === $sseo_vals && 3 === count( Simple_SEO_WooCommerce::pages() ),
			$sseo_vals
		);
		$sseo_wc_hidden = array();
		foreach ( array( 'hidden', 'catalog', 'search' ) as $sseo_name ) {
			$sseo_wc_hidden[ $sseo_name ] = $sseo_wc_product( array( 'name' => 'Woovisible ' . $sseo_name, 'regular_price' => '5' ) );
			$sseo_product                 = wc_get_product( $sseo_wc_hidden[ $sseo_name ] );
			$sseo_product->set_catalog_visibility( $sseo_name );
			$sseo_product->save();
		}
		wp_update_post( array( 'ID' => $sseo_wc_arch, 'post_status' => 'publish' ) );
		$sseo_pages    = array_map( static fn( WP_Post $post ): int => (int) $post->ID, Simple_SEO_Sitemaps::posts( 'page', '', 10000 ) );
		$sseo_products = array_map( static fn( WP_Post $post ): int => (int) $post->ID, Simple_SEO_Sitemaps::posts( 'product', '', 10000 ) );
		$sseo_vals     = array(
			array_values( array_intersect( array_merge( Simple_SEO_WooCommerce::pages(), array( $sseo_wc_shop ) ), $sseo_pages ) ),
			in_array( $sseo_wc_arch, $sseo_pages, true ),
			array_values( array_intersect( $sseo_wc_hidden, $sseo_products ) ),
			in_array( $sseo_wc_table, $sseo_products, true ),
			Simple_SEO_WooCommerce::hidden_products(),
			Simple_SEO_WooCommerce::sitemap_exclude( array( 3 ), 'term', 'product_cat' ),
			Simple_SEO_WooCommerce::sitemap_exclude( array( 3 ), 'post', 'post' ),
			Simple_SEO_WooCommerce::sitemap_exclude( 'x', 'post', 'page' ),
			Simple_SEO_WooCommerce::sitemap_exclude( array( 3 ), 'term', 'page' ),
			Simple_SEO_WooCommerce::sitemap_exclude( array( 3 ), 'post', 'page' ),
		);
		sseo_check(
			'the sitemaps: no cart, checkout, account, nor the shop page (the sitemap of products opens with it); no product hidden from the catalog and the search, those hidden from one of them listed',
			array() === $sseo_vals[0] && true === $sseo_vals[1] && array( $sseo_wc_hidden['catalog'], $sseo_wc_hidden['search'] ) === $sseo_vals[2] && true === $sseo_vals[3]
				&& array( $sseo_wc_hidden['hidden'] ) === $sseo_vals[4] && array( 3 ) === $sseo_vals[5] && array( 3 ) === $sseo_vals[6] && 'x' === $sseo_vals[7] && array( 3 ) === $sseo_vals[8]
				&& array_merge( array( 3 ), Simple_SEO_WooCommerce::pages(), array( $sseo_wc_shop ) ) === $sseo_vals[9],
			$sseo_vals
		);
	}

	update_option( Simple_SEO_Schema::OPTION, $sseo_wc_schema );
	Simple_SEO_Settings::flush();
	$GLOBALS['wp_query'] = $sseo_wc_query;
	unset( $GLOBALS['wp_actions']['wp'] );
	if ( null !== $sseo_wc_actions ) {
		$GLOBALS['wp_actions']['wp'] = $sseo_wc_actions;
	}
	Simple_SEO_Context::reset();

	// ------------------------------------------------------------------------------------------
	sseo_section( 'Translation' );

	$sseo_mo = SIMPLE_SEO_DIR . 'languages/simple-seo-uk.mo';
	sseo_check( 'the Ukrainian translation exists', is_readable( $sseo_mo ) );
	unload_textdomain( 'simple-seo' );
	load_textdomain( 'simple-seo', $sseo_mo );
	sseo_check( 'a field label is translated', 'SEO-заголовок' === __( 'SEO title', 'simple-seo' ), __( 'SEO title', 'simple-seo' ) );
	sseo_check( 'a tab name is translated', 'Доступ' === __( 'Access', 'simple-seo' ) && 'Заголовки' === __( 'Titles', 'simple-seo' ), __( 'Titles', 'simple-seo' ) );
	sseo_check( 'the structure button is translated', 'Вставити структуру' === __( 'Insert structure', 'simple-seo' ) );
	sseo_check( 'the Indexing tab is translated', 'Індексація' === __( 'Indexing', 'simple-seo' ) );
	sseo_check( 'the Social networks tab is translated', 'Соцмережі' === __( 'Social networks', 'simple-seo' ) );
	sseo_check( 'the Special pages tab is translated', 'Спецсторінки' === __( 'Special pages', 'simple-seo' ) );
	sseo_check( 'the sitemap switch is translated', 'Створювати XML-карту сайту' === __( 'Create an XML sitemap', 'simple-seo' ) );
	sseo_check( 'the breadcrumbs are translated', 'Хлібні крихти' === __( 'Breadcrumbs', 'simple-seo' ) && 'Головна' === __( 'Home', 'simple-seo' ) && '%s у хлібних крихтах' === __( '%s in breadcrumbs', 'simple-seo' ) );
	sseo_check( 'the llms.txt tab is translated', 'Посилань у розділі' === __( 'Links in a section', 'simple-seo' ) && 'Інші мови:' === __( 'Other languages:', 'simple-seo' ) );
	sseo_check( 'the Clean-up tab is translated', 'Чистка коду' === __( 'Clean-up', 'simple-seo' ) && 'Версія WordPress' === __( 'WordPress version', 'simple-seo' ) );
	sseo_check( 'the Files tab is translated', 'Файли' === __( 'Files', 'simple-seo' ) && 'Історія' === __( 'History', 'simple-seo' ) );
	sseo_check( 'the Import tab is translated', 'Імпорт' === __( 'Import', 'simple-seo' ) && 'Імпортувати з %s' === __( 'Import from %s', 'simple-seo' ) && 'шаблони: %s' === __( 'templates: %s', 'simple-seo' ) && 'Прибрати дані %s' === __( 'Remove the data of %s', 'simple-seo' ) );
	sseo_check( 'the search result preview is translated', 'Вигляд у пошуковій видачі' === __( 'Search result preview', 'simple-seo' ) && 'SEO-заголовок: символів — %s, пошуковик його обріже.' === __( 'SEO title: %s characters, search engines will cut it.', 'simple-seo' ) );
	sseo_check( 'the content analysis is translated', 'Аналіз контенту' === __( 'Content analysis', 'simple-seo' ) && 'SEO-оцінка: %s зі 100' === __( 'SEO score: %s of 100', 'simple-seo' ) );
	sseo_check( 'readability and the column of scores are translated', 'Читабельність: %s зі 100' === __( 'Readability: %s of 100', 'simple-seo' ) && 'Читабельність: %s' === __( 'Readability: %s', 'simple-seo' ) && 'Речення поспіль починаються з різних слів.' === __( 'Sentences in a row start with different words.', 'simple-seo' ) );
	sseo_check( 'bulk editing is translated', 'Масове редагування' === __( 'Bulk edit', 'simple-seo' ) && 'Без власного SEO-заголовка' === __( 'Without an SEO title of their own', 'simple-seo' ) && 'Збережено: %s.' === __( 'Saved: %s.', 'simple-seo' ) );
	sseo_check( 'AI is translated', 'Написати з AI' === __( 'Write with AI', 'simple-seo' ) && 'Варіанти' === __( 'Variants', 'simple-seo' ) && 'AI не зміг це написати: %s' === __( 'The AI could not write it: %s', 'simple-seo' ) && 'Оберіть варіант:' === __( 'Choose one:', 'simple-seo' ) );
	sseo_check( 'the alt texts by AI are translated', 'Написати alt-текст з AI' === __( 'Write the alt text with AI', 'simple-seo' ) && 'AI пише %1$s з %2$s…' === __( 'The AI writes %1$s of %2$s…', 'simple-seo' ) && 'Alt-текст зображень' === __( 'Alt text of images', 'simple-seo' ) );
	sseo_check( 'a string with context is translated', 'F Y' === _x( 'F Y', 'month archive date format', 'simple-seo' ) && 'Сторінка %1$d з %2$d' === __( 'Page %1$d of %2$d', 'simple-seo' ) );
	unload_textdomain( 'simple-seo' );

	// ------------------------------------------------------------------------------------------
	sseo_section( 'Uninstall' );

	update_option( 'simple_seo_sseo_extra', array( 'x' => 1 ) );
	file_put_contents( get_home_path() . Simple_SEO_Files::DISK_COPY, "# copy\n" );
	set_transient( 'simple_seo_llms_default', 'x', DAY_IN_SECONDS );
	// uninstall.php runs without the plugin: none of its hooks drop the cache on the way.
	foreach ( array( 'added_option', 'updated_option', 'deleted_option' ) as $sseo_name ) {
		remove_action( $sseo_name, array( Simple_SEO_Llms::class, 'option_changed' ) );
	}
	if ( ! defined( 'WP_UNINSTALL_PLUGIN' ) ) {
		define( 'WP_UNINSTALL_PLUGIN', 'simple-seo/simple-seo.php' );
	}
	wp_schedule_single_event( time() + 60, Simple_SEO_IndexNow::EVENT );
	wp_schedule_event( time() + 60, 'daily', Simple_SEO_Monitor::EVENT );
	wp_schedule_single_event( time() + 60, Simple_SEO_Audit::EVENT );
	wp_schedule_single_event( time() + 60, Simple_SEO_Links::RETRY );
	wp_schedule_single_event( time() + 60, Simple_SEO_AI::ALT_EVENT, array( 123 ) );
	include SIMPLE_SEO_DIR . 'uninstall.php';
	sseo_check( 'uninstall drops a batch of IndexNow waiting', false === wp_next_scheduled( Simple_SEO_IndexNow::EVENT ) );
	sseo_check( 'uninstall drops the table of the monitor of 404s and its clean-up', ! $GLOBALS['wpdb']->get_var( $GLOBALS['wpdb']->prepare( 'SHOW TABLES LIKE %s', Simple_SEO_Monitor::table() ) ) && false === wp_next_scheduled( Simple_SEO_Monitor::EVENT ) );
	sseo_check( 'uninstall drops the report of the audit, its run and a step waiting', ! $GLOBALS['wpdb']->get_var( $GLOBALS['wpdb']->prepare( 'SHOW TABLES LIKE %s', Simple_SEO_Audit::table() ) ) && false === wp_next_scheduled( Simple_SEO_Audit::EVENT ) && false === get_option( Simple_SEO_Audit::RUN ) );
	sseo_check( 'uninstall drops the alt texts of new images the AI has yet to write', false === wp_next_scheduled( Simple_SEO_AI::ALT_EVENT, array( 123 ) ) );
	sseo_check( 'uninstall drops the links of the audit and a check of them waiting', ! $GLOBALS['wpdb']->get_var( $GLOBALS['wpdb']->prepare( 'SHOW TABLES LIKE %s', Simple_SEO_Links::table() ) ) && false === wp_next_scheduled( Simple_SEO_Links::RETRY ) );
	$sseo_left = $GLOBALS['wpdb']->get_col( "SELECT option_name FROM {$GLOBALS['wpdb']->options} WHERE option_name LIKE 'simple\\_seo\\_%'" );
	sseo_check( 'uninstall removes every simple_seo_ option', array() === $sseo_left, $sseo_left );
	sseo_check( 'uninstall removes the copy of .htaccess', ! is_file( get_home_path() . Simple_SEO_Files::DISK_COPY ) );
	sseo_check( 'uninstall removes the cached llms.txt', array() === $GLOBALS['wpdb']->get_col( "SELECT option_name FROM {$GLOBALS['wpdb']->options} WHERE option_name LIKE '\\_transient%simple\\_seo\\_%'" ) );
	sseo_check( 'uninstall leaves the options cache consistent', null === get_option( Simple_SEO_Plugin::VERSION_OPTION, null ) && null === get_option( Simple_SEO_Access::OPTION, null ) );
	sseo_check( 'uninstall keeps the SEO fields of posts', 'Welcome {sep} {site}' === Simple_SEO_Fields::post_value( $sseo_p['front'], 'title' ) );
	sseo_check( 'uninstall keeps the SEO fields of terms', 'Saved from the term form' === Simple_SEO_Fields::term_value( $sseo_cat_id, 'title' ) );
	Simple_SEO_Settings::flush();
	Simple_SEO_Plugin::maybe_upgrade();
	sseo_check( 'the next request installs the rows again, and the table of the monitor', null !== get_option( Simple_SEO_Access::OPTION, null ) && SIMPLE_SEO_VERSION === get_option( Simple_SEO_Plugin::VERSION_OPTION ) && (bool) $GLOBALS['wpdb']->get_var( $GLOBALS['wpdb']->prepare( 'SHOW TABLES LIKE %s', Simple_SEO_Monitor::table() ) ) && (bool) $GLOBALS['wpdb']->get_var( $GLOBALS['wpdb']->prepare( 'SHOW TABLES LIKE %s', Simple_SEO_Audit::table() ) ) && (bool) $GLOBALS['wpdb']->get_var( $GLOBALS['wpdb']->prepare( 'SHOW TABLES LIKE %s', Simple_SEO_Links::table() ) ) );

	// Last: REST_REQUEST stays defined for the rest of the run.
	unset( $GLOBALS['current_screen'] );
	delete_post_meta( $sseo['posts']['scored'], Simple_SEO_Scores::META );
	define( 'REST_REQUEST', true );
	wp_update_post( array( 'ID' => $sseo['posts']['scored'], 'post_title' => 'Scored through the REST API' ) );
	sseo_check( 'scores: a post saved through the REST API (the block editor, an agent) is analysed', null !== Simple_SEO_Scores::get( get_post( $sseo['posts']['scored'] ) ) );
} catch ( Throwable $sseo_error ) {
	sseo_check( 'no exception', false, get_class( $sseo_error ) . ': ' . $sseo_error->getMessage() . ' at ' . $sseo_error->getFile() . ':' . $sseo_error->getLine() );
} finally {
	$sseo_cleanup();
}

$sseo_r = $GLOBALS['sseo_results'];
echo "\n{$sseo_r['pass']} passed, {$sseo_r['fail']} failed\n";
if ( $sseo_r['fail'] > 0 ) {
	WP_CLI::halt( 1 );
}
